INSERT INTO categories (id, name, description) VALUES ('insurance-exam', 'Insurance Exams', 'Insurance awareness, reasoning, and aptitude for LIC, GIC, and NIACL recruitment exams.');
INSERT INTO question_sets (id, owner_user_id, title, track, visibility, created_at, approved_at, approved_by) VALUES ('insurance-exam-bank', NULL, 'Insurance Exam Prep', 'insurance', 'shared', '2026-11-14T06:17:56.365Z', '2026-11-14T06:17:56.365Z', NULL);
INSERT INTO question_set_categories (set_id, category_id) VALUES ('insurance-exam-bank', 'insurance-exam');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00001', 'insurance-exam-bank', 'Insurance Awareness & Fundamentals', 0, 0, 'What does IRDAI stand for, and when was it given statutory status?', 'IRDAI stands for the **Insurance Regulatory and Development Authority of India**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00002', 'insurance-exam-bank', 'Insurance Awareness & Fundamentals', 0, 1, 'Where is the headquarters of IRDAI located?', 'IRDAI''s headquarters is in **Hyderabad**, Telangana.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00003', 'insurance-exam-bank', 'Insurance Awareness & Fundamentals', 0, 2, 'What is the full form of IRDA Act, 1999 and what is its core purpose?', 'It is the **Insurance Regulatory and Development Authority Act, 1999**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00004', 'insurance-exam-bank', 'Insurance Awareness & Fundamentals', 0, 3, 'What is ''sum assured'' in a life insurance policy?', 'Sum assured is the **guaranteed amount** the insurer promises to pay the nominee/beneficiary on the death of the policyholder, or on maturity in some plans.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00005', 'insurance-exam-bank', 'Insurance Awareness & Fundamentals', 0, 4, 'Define ''premium'' in the context of an insurance policy.', 'Premium is the **amount paid by the policyholder** to the insurer, periodically or as a lump sum, in exchange for the risk cover provided under the policy.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00006', 'insurance-exam-bank', 'Insurance Awareness & Fundamentals', 0, 5, 'What is the ''surrender value'' of a life insurance policy?', 'Surrender value is the **amount payable to the policyholder** if the policy is voluntarily terminated before maturity, after paying premiums for a minimum required period (usually two to three years).
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00007', 'insurance-exam-bank', 'Insurance Awareness & Fundamentals', 0, 6, 'What is a ''rider'' in insurance, and name two common types.', 'A rider is an **optional add-on benefit** attached to a base insurance policy for an additional premium, providing extra coverage beyond the base plan.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00008', 'insurance-exam-bank', 'Insurance Awareness & Fundamentals', 0, 7, 'What is ''nomination'' under a life insurance policy?', 'Nomination is the process by which a policyholder names a person (the **nominee**) to receive the policy proceeds in case of the policyholder''s death.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00009', 'insurance-exam-bank', 'Insurance Awareness & Fundamentals', 0, 8, 'How does ''nomination'' differ from ''assignment'' under the Insurance Act, 1938?', '**Nomination (Section 39)** merely designates who will receive the claim amount; it does not transfer ownership of the policy, and the nominee holds the money in trust for the legal heirs unless they are a beneficial nominee.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00010', 'insurance-exam-bank', 'Insurance Awareness & Fundamentals', 0, 9, 'What is a ''term insurance plan''?', 'A term plan is a **pure life insurance product** that provides a death benefit (sum assured) to the nominee if the policyholder dies during the policy term, and pays nothing on survival.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00011', 'insurance-exam-bank', 'Insurance Awareness & Fundamentals', 0, 10, 'What is a ''whole life insurance policy''?', 'A whole life policy provides **life cover for the entire life** of the policyholder (traditionally up to age 99 or 100), rather than for a fixed term.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00012', 'insurance-exam-bank', 'Insurance Awareness & Fundamentals', 0, 11, 'What is an ''endowment policy''?', 'An endowment policy is a **savings-cum-insurance** plan that pays the sum assured (plus accrued bonuses) either on **maturity** if the policyholder survives the term, or on **death** during the term.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00013', 'insurance-exam-bank', 'Insurance Awareness & Fundamentals', 0, 12, 'What does ULIP stand for, and how does it work?', 'ULIP stands for **Unit Linked Insurance Plan**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00014', 'insurance-exam-bank', 'Insurance Awareness & Fundamentals', 0, 13, 'What is a ''money-back policy''?', 'A money-back policy pays out a percentage of the sum assured at **periodic intervals** during the policy term (called survival benefits), rather than only at maturity.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00015', 'insurance-exam-bank', 'Insurance Awareness & Fundamentals', 0, 14, 'What is an ''annuity'' plan in insurance?', 'An annuity plan is a **retirement/pension product** where the policyholder pays a lump sum or periodic premiums (accumulation phase) and, in return, receives regular payouts (annuity/vesting phase) for life or a fixed period.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00016', 'insurance-exam-bank', 'Insurance Awareness & Fundamentals', 0, 15, 'What is the ''grace period'' in a life insurance policy?', 'The grace period is the **additional time allowed** after the premium due date, during which the policyholder can pay the premium without the policy lapsing and without losing continuity of benefits.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00017', 'insurance-exam-bank', 'Insurance Awareness & Fundamentals', 0, 16, 'What happens when a life insurance policy ''lapses''?', 'A policy lapses when the premium is **not paid even after the grace period**, causing the risk cover to stop.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00018', 'insurance-exam-bank', 'Insurance Awareness & Fundamentals', 0, 17, 'What is the ''free-look period'' in insurance, as mandated by IRDAI?', 'The free-look period allows a policyholder to **review and return** a newly issued policy if they disagree with its terms, getting a refund of premium (minus certain deductions like stamp duty and medical costs).
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00019', 'insurance-exam-bank', 'Insurance Awareness & Fundamentals', 0, 18, 'What is ''bonus'' in a traditional with-profit life insurance policy?', 'Bonus is the **share of profits** that a life insurer distributes to policyholders of participating (with-profit) policies, based on the insurer''s actuarial valuation and investment surplus.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00020', 'insurance-exam-bank', 'Insurance Awareness & Fundamentals', 0, 19, 'What is ''insurable interest'' and why is it a fundamental principle of insurance?', 'Insurable interest means the policyholder must stand to suffer a **genuine financial loss** from the event being insured against (e.g., a person has insurable interest in their own life, or in a family member''s life).
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00021', 'insurance-exam-bank', 'Insurance Awareness & Fundamentals', 0, 20, 'What is the principle of ''uberrima fides'' (utmost good faith) in insurance contracts?', 'Uberrima fides means both the insurer and the insured must **disclose all material facts** honestly and completely while entering an insurance contract.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00022', 'insurance-exam-bank', 'Insurance Awareness & Fundamentals', 0, 21, 'What is the principle of ''indemnity'' in general insurance?', 'Indemnity means the insurer agrees to **compensate the insured for the actual financial loss suffered**, restoring them to the same financial position as before the loss — no more, no less.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00023', 'insurance-exam-bank', 'Insurance Awareness & Fundamentals', 0, 22, 'What is ''subrogation'' in insurance?', 'Subrogation is the right of the insurer, **after paying a claim**, to step into the shoes of the insured and pursue recovery from a third party who caused the loss.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00024', 'insurance-exam-bank', 'Insurance Awareness & Fundamentals', 0, 23, 'What is the principle of ''contribution'' in general insurance?', 'Contribution applies when the **same risk is insured with more than one insurer**; each insurer is liable to pay only a proportionate share of the loss, based on the sum insured by each.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00025', 'insurance-exam-bank', 'Insurance Awareness & Fundamentals', 0, 24, 'What is ''proximate cause'' in insurance claims?', 'Proximate cause is the **dominant, most direct cause** of a loss, used to determine whether a claim is payable under a policy.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00026', 'insurance-exam-bank', 'Insurance Awareness & Fundamentals', 0, 25, 'Differentiate between a ''warranty'' and a ''representation'' in an insurance contract.', 'A **warranty** is a specific, material condition that must be **strictly and exactly complied with**; any breach, even an immaterial one, can void the contract.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00027', 'insurance-exam-bank', 'Insurance Awareness & Fundamentals', 0, 26, 'What is ''underwriting'' in the insurance industry?', 'Underwriting is the process by which an insurer **evaluates the risk** of insuring a person or asset, deciding whether to accept the risk, at what premium, and on what terms and conditions.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00028', 'insurance-exam-bank', 'Insurance Awareness & Fundamentals', 0, 27, 'What is ''adverse selection'' in insurance?', 'Adverse selection occurs when people who are at **higher risk** are more likely to seek insurance than low-risk individuals, because they have better knowledge of their own risk than the insurer does.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00029', 'insurance-exam-bank', 'Insurance Awareness & Fundamentals', 0, 28, 'What is ''moral hazard'' in the context of insurance?', 'Moral hazard refers to the **change in behaviour** of an insured person who, once covered, may take less care to prevent a loss (or even act dishonestly), because the financial consequences fall on the insurer.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00030', 'insurance-exam-bank', 'Insurance Awareness & Fundamentals', 0, 29, 'What is ''reinsurance'', and why do insurers need it?', 'Reinsurance is **insurance for insurers** — a primary (ceding) insurer transfers part of its risk to another insurer (the reinsurer) in exchange for a share of the premium.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00031', 'insurance-exam-bank', 'Insurance Awareness & Fundamentals', 0, 30, 'Differentiate between ''facultative'' and ''treaty'' reinsurance.', '**Facultative reinsurance** covers a single, specific risk, with both the ceding insurer and reinsurer free to accept or reject that particular risk individually.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00032', 'insurance-exam-bank', 'Insurance Awareness & Fundamentals', 0, 31, 'What is the difference between ''proportional'' and ''non-proportional'' reinsurance?', 'In **proportional reinsurance**, the reinsurer shares premiums and losses in an agreed proportion with the ceding insurer (e.g., quota share, surplus treaty).
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00033', 'insurance-exam-bank', 'Insurance Awareness & Fundamentals', 0, 32, 'What is GIC Re, and what is its current primary role?', 'GIC Re (**General Insurance Corporation of India**) was incorporated on **22 November 1972** as the holding company for the four nationalised general insurers after the General Insurance Business (Nationalisation) Act, 1972.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00034', 'insurance-exam-bank', 'Insurance Awareness & Fundamentals', 0, 33, 'Name the four public-sector general insurance companies formed after the 1972 nationalisation.', 'The four nationalised general insurers are:
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00035', 'insurance-exam-bank', 'Insurance Awareness & Fundamentals', 0, 34, 'When was the Life Insurance Corporation of India (LIC) established, and under which Act?', 'LIC was established on **1 September 1956** under the **Life Insurance Corporation Act, 1956**, which nationalised the life insurance business in India by merging over 240 private life insurers and provident societies into a single entity.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00036', 'insurance-exam-bank', 'Insurance Awareness & Fundamentals', 0, 35, 'Where is the headquarters of LIC of India?', 'LIC''s headquarters (Central Office) is located in **Mumbai**, Maharashtra.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00037', 'insurance-exam-bank', 'Insurance Awareness & Fundamentals', 0, 36, 'What is NIACL, and when was it founded?', 'NIACL stands for **National Insurance Company Limited**, one of the four public-sector general insurers formed after the 1972 nationalisation.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00038', 'insurance-exam-bank', 'Insurance Awareness & Fundamentals', 0, 37, 'What is the Insurance Information Bureau of India (IIB)?', 'IIB is a body set up to create a **centralised data repository** for the Indian insurance industry, collecting policy and claims data from insurers to help detect fraud, improve underwriting, and support actuarial and regulatory analysis.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00039', 'insurance-exam-bank', 'Insurance Awareness & Fundamentals', 0, 38, 'What is the Insurance Institute of India (III)?', 'The Insurance Institute of India, headquartered in **Mumbai**, is the premier professional body that conducts **examinations and certifications** (such as Licentiate, Associate, and Fellowship) for insurance professionals in India.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00040', 'insurance-exam-bank', 'Insurance Awareness & Fundamentals', 0, 39, 'What is the Insurance Ombudsman scheme?', 'The Insurance Ombudsman scheme provides policyholders a **free, speedy grievance redressal mechanism** for disputes with insurers (such as claim rejection or delay) without going through lengthy litigation.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00041', 'insurance-exam-bank', 'Insurance Awareness & Fundamentals', 0, 40, 'What is the monetary limit for complaints that can be taken up by the Insurance Ombudsman?', 'The Insurance Ombudsman can entertain complaints involving a claim amount up to **₹50 lakh**, including both the value of the claim and any expenses/damages claimed.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00042', 'insurance-exam-bank', 'Insurance Awareness & Fundamentals', 0, 41, 'What is a ''deductible'' in a general/health insurance policy?', 'A deductible is the **portion of a claim amount** that the policyholder must bear out of pocket before the insurer starts paying; it can be a fixed amount or a percentage.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00043', 'insurance-exam-bank', 'Insurance Awareness & Fundamentals', 0, 42, 'What is ''co-payment'' (co-pay) in health insurance?', 'Co-payment is a clause requiring the policyholder to pay a **fixed percentage of every claim amount** themselves, with the insurer paying the rest, regardless of the claim size.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00044', 'insurance-exam-bank', 'Insurance Awareness & Fundamentals', 0, 43, 'What is the ''claim settlement ratio'' of an insurer?', 'Claim settlement ratio is the **percentage of claims an insurer has settled** out of the total claims it received in a financial year.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00045', 'insurance-exam-bank', 'Insurance Awareness & Fundamentals', 0, 44, 'What is a ''policy exclusion''?', 'A policy exclusion is a **specific condition, event, or circumstance that the insurer will not cover** under the policy, explicitly listed in the policy document.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00046', 'insurance-exam-bank', 'Insurance Awareness & Fundamentals', 0, 45, 'What is the suicide clause typically found in Indian life insurance policies?', 'Under IRDAI regulations, if a policyholder dies by suicide **within 12 months** of the start/revival of the policy, the insurer is liable to pay **at least 80% of the premiums paid** (or the surrender value, whichever is higher), provided the policy is in force.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00047', 'insurance-exam-bank', 'Insurance Awareness & Fundamentals', 0, 46, 'What is a ''participating'' versus a ''non-participating'' life insurance policy?', 'A **participating (with-profit) policy** entitles the policyholder to share in the insurer''s profits through bonuses declared periodically.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00048', 'insurance-exam-bank', 'Insurance Awareness & Fundamentals', 0, 47, 'What is ''micro-insurance'' and who typically regulates its products in India?', 'Micro-insurance refers to **low-premium, low-sum-assured insurance products** designed for low-income and economically vulnerable sections of society, often distributed through NGOs, SHGs, and microfinance institutions.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00049', 'insurance-exam-bank', 'Insurance Awareness & Fundamentals', 0, 48, 'What are IRDAI''s ''Bima Trinity'' initiatives?', 'The Bima Trinity consists of three related IRDAI initiatives aimed at achieving ''Insurance for All'':
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00050', 'insurance-exam-bank', 'Insurance Awareness & Fundamentals', 0, 49, 'What is ''Bima Sugam'' designed to do?', 'Bima Sugam is envisaged as a **one-stop digital insurance marketplace/exchange** where customers can compare, buy, and service life, health, and general insurance policies, and insurers can settle claims, all on a single IRDAI-backed platform.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00051', 'insurance-exam-bank', 'Insurance Awareness & Fundamentals', 0, 50, 'What is ''Bima Vistaar''?', 'Bima Vistaar is a **low-cost, bundled composite insurance product** proposed by IRDAI covering life, personal accident, property damage, and basic health/hospitalisation risks in a single affordable policy, aimed at rural and underserved customers.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00052', 'insurance-exam-bank', 'Insurance Awareness & Fundamentals', 0, 51, 'What is ''Bima Vahak''?', 'Bima Vahak is a proposed **women-centric, dedicated distribution channel** under IRDAI''s reforms, intended to have at least one trained woman insurance correspondent in every gram panchayat to spread insurance awareness and facilitate policy sales and claim servicing at the grassroots level.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00053', 'insurance-exam-bank', 'Insurance Awareness & Fundamentals', 0, 52, 'What is the statutory minimum solvency margin ratio that Indian insurers must maintain?', 'Indian insurers must maintain a minimum solvency margin (control level of solvency) with an **Available Solvency Margin to Required Solvency Margin ratio of at least 1.5 (150%)**, as prescribed by IRDAI, to ensure they can meet their claim obligations.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00054', 'insurance-exam-bank', 'Insurance Awareness & Fundamentals', 0, 53, 'What does ''Section 45'' of the Insurance Act, 1938 deal with?', 'Section 45 lays down the **incontestability rule**: a life insurance policy cannot be questioned by the insurer on grounds of mis-statement or suppression of facts after it has been in force for a continuous period of **three years** from the date of issue, revival, or rider addition, except in cases of proven fraud.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00055', 'insurance-exam-bank', 'Insurance Awareness & Fundamentals', 0, 54, 'What is a ''third-party insurance'' in the context of motor insurance, and is it mandatory in India?', 'Third-party insurance covers the insured''s **legal liability towards a third party** (another person or their property) for death, injury, or damage caused by the insured''s vehicle.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00056', 'insurance-exam-bank', 'Insurance Awareness & Fundamentals', 0, 55, 'What is ''comprehensive'' motor insurance, as opposed to third-party-only cover?', 'Comprehensive motor insurance covers **both third-party liability and ''own damage''** — i.e., damage to the insured''s own vehicle from accidents, theft, fire, and natural calamities — unlike a third-party-only policy, which covers liability to others alone.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00057', 'insurance-exam-bank', 'Insurance Awareness & Fundamentals', 0, 56, 'What is the ''No Claim Bonus'' (NCB) in motor insurance?', 'No Claim Bonus is a **discount on the own-damage premium** offered to a policyholder for every claim-free year, which can accumulate up to a maximum (commonly 50%) over several consecutive claim-free years.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00058', 'insurance-exam-bank', 'Insurance Awareness & Fundamentals', 0, 57, 'What is the IRDAI (Protection of Policyholders'' Interests) Regulations meant to ensure?', 'These regulations lay down norms to protect policyholders, covering areas such as **mandatory disclosures** by insurers, prescribed timelines for claim settlement, free-look provisions, and grievance redressal procedures, to ensure fair treatment and transparency towards customers.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00059', 'insurance-exam-bank', 'Insurance Awareness & Fundamentals', 0, 58, 'What is a ''Keyman Insurance Policy''?', 'Keyman insurance is a life insurance policy taken by a **business/company on the life of a key employee** (such as a top executive) whose skills are critical to the business, with the company as both proposer/payer and beneficiary, to protect against financial loss from that person''s untimely death.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00060', 'insurance-exam-bank', 'Insurance Awareness & Fundamentals', 0, 59, 'What is the difference between ''fixed benefit'' and ''indemnity-based'' health insurance plans?', '**Fixed benefit (benefit-based) plans** pay a predetermined lump sum on diagnosis of a covered illness/event, regardless of actual treatment cost (e.g., critical illness cover).
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00061', 'insurance-exam-bank', 'Insurance Awareness & Fundamentals', 0, 60, 'What is a ''Top-up'' health insurance plan?', 'A top-up plan provides **additional health cover beyond a specified threshold (deductible)**, kicking in only after a single large claim crosses that deductible amount, making it a cost-effective way to boost the overall sum insured.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00062', 'insurance-exam-bank', 'Insurance Awareness & Fundamentals', 0, 61, 'What is a ''Super Top-up'' health plan, and how does it differ from a regular top-up?', 'A super top-up plan also activates once claims cross a deductible, but unlike a regular top-up (which considers each claim/hospitalisation separately against the deductible), a super top-up considers the **aggregate of all claims in a policy year** against the deductible.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00063', 'insurance-exam-bank', 'Insurance Awareness & Fundamentals', 0, 62, 'What is ''portability'' in health insurance?', 'Portability is the facility that allows a policyholder to **switch health insurers** (or plans within the same insurer) while retaining credit for the **waiting periods already served**, such as those for pre-existing diseases, as mandated by IRDAI guidelines.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00064', 'insurance-exam-bank', 'Insurance Awareness & Fundamentals', 0, 63, 'What is the ''waiting period'' in health insurance, with respect to pre-existing diseases?', 'The waiting period is the time a policyholder must wait after buying a policy before claims related to **pre-existing diseases** become payable.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00065', 'insurance-exam-bank', 'Insurance Awareness & Fundamentals', 0, 64, 'What is a ''cashless'' claim facility in health insurance?', 'Cashless claim facility allows a policyholder to get treatment at a **network hospital** (empanelled by the insurer/TPA) without paying the hospital bill upfront; the insurer settles the bill directly with the hospital, subject to policy terms.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00066', 'insurance-exam-bank', 'Insurance Awareness & Fundamentals', 0, 65, 'What is a ''Third Party Administrator'' (TPA) in health insurance?', 'A TPA is a licensed intermediary that handles **claims processing, cashless authorisation, and hospital network management** on behalf of health insurers, acting as a bridge between policyholders, hospitals, and insurers.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00067', 'insurance-exam-bank', 'Insurance Awareness & Fundamentals', 0, 66, 'What is ''actuarial science'' and what role does an actuary play in insurance?', 'Actuarial science applies mathematics, statistics, and probability theory to assess **financial risk**, particularly mortality, morbidity, and investment risk.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00068', 'insurance-exam-bank', 'Insurance Awareness & Fundamentals', 0, 67, 'What is a ''mortality table'' used for in life insurance?', 'A mortality table shows the **probability of death at each age** for a given population, derived from historical data.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00069', 'insurance-exam-bank', 'Insurance Awareness & Fundamentals', 0, 68, 'What is the IRDAI (Insurance Advertisement and Disclosure) Regulations primarily meant to prevent?', 'These regulations are meant to prevent **misleading advertisements** and mis-selling by requiring insurers and agents to ensure that promotional material is clear, fair, and not deceptive about policy benefits, returns, or terms.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00070', 'insurance-exam-bank', 'Insurance Awareness & Fundamentals', 0, 69, 'What is the difference between an ''insurance agent'' and an ''insurance broker''?', 'An **insurance agent** represents and works on behalf of **one specific insurer** (or a composite agent for a limited set of insurers) and sells that insurer''s products.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00071', 'insurance-exam-bank', 'Insurance Awareness & Fundamentals', 0, 70, 'What is a ''Point of Sales Person'' (POSP) in Indian insurance distribution?', 'A POSP is a certified individual authorised to sell **standard, simplified insurance products** (that need minimal explanation, such as basic term or standard health policies) after completing a short IRDAI-mandated training and certification, without needing a full agent license.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00072', 'insurance-exam-bank', 'Insurance Awareness & Fundamentals', 0, 71, 'What does IRDAI''s ''Insurance for All by 2047'' vision aim to achieve?', '''Insurance for All by 2047'' is IRDAI''s stated mission to ensure **every citizen has appropriate life, health, and property insurance**, and every enterprise is covered by suitable insurance products, by the 100th year of India''s independence.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00073', 'insurance-exam-bank', 'Banking & Financial Awareness', 1, 0, 'When was the Reserve Bank of India (RBI) established, and under which Act?', 'The RBI was established on **1 April 1935** under the **Reserve Bank of India Act, 1934**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00074', 'insurance-exam-bank', 'Banking & Financial Awareness', 1, 1, 'Where is the RBI headquartered, and who issues currency notes in India?', 'The RBI is headquartered in **Mumbai**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00075', 'insurance-exam-bank', 'Banking & Financial Awareness', 1, 2, 'What is the ''repo rate'' and what does it represent?', 'The repo rate is the rate at which the **RBI lends short-term funds to commercial banks** against government securities, under a repurchase agreement.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00076', 'insurance-exam-bank', 'Banking & Financial Awareness', 1, 3, 'What is the ''reverse repo rate''?', 'Reverse repo rate is the rate at which the **RBI borrows funds from commercial banks**, absorbing excess liquidity from the banking system.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00077', 'insurance-exam-bank', 'Banking & Financial Awareness', 1, 4, 'What is the ''Cash Reserve Ratio'' (CRR)?', 'CRR is the **minimum percentage of a bank''s Net Demand and Time Liabilities (NDTL)** that it must maintain as cash reserves with the RBI, in the form of a deposit.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00078', 'insurance-exam-bank', 'Banking & Financial Awareness', 1, 5, 'What is the ''Statutory Liquidity Ratio'' (SLR)?', 'SLR is the **minimum percentage of NDTL** that banks must maintain in the form of liquid assets such as cash, gold, and approved government securities, **before** extending credit.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00079', 'insurance-exam-bank', 'Banking & Financial Awareness', 1, 6, 'What is the ''Marginal Standing Facility'' (MSF)?', 'MSF is a facility under which **scheduled commercial banks can borrow overnight funds from the RBI** against government securities, even by dipping into their SLR holdings, usually at a rate higher than the repo rate.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00080', 'insurance-exam-bank', 'Banking & Financial Awareness', 1, 7, 'What is the ''Bank Rate'' as used by the RBI?', 'Bank Rate is the rate at which the **RBI provides long-term loans or rediscounts bills** for banks and financial institutions, without any collateral.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00081', 'insurance-exam-bank', 'Banking & Financial Awareness', 1, 8, 'What is the Monetary Policy Committee (MPC) of the RBI?', 'The MPC is a **six-member committee** (three from the RBI, including the Governor as chairperson, and three external members appointed by the Government) responsible for fixing the policy repo rate to achieve the inflation target, as mandated under the **RBI Act (amended in 2016)**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00082', 'insurance-exam-bank', 'Banking & Financial Awareness', 1, 9, 'What is India''s current flexible inflation targeting framework?', 'Under the flexible inflation targeting (FIT) framework, the RBI is mandated to maintain **Consumer Price Index (CPI) inflation at 4%, with a tolerance band of +/- 2%** (i.e., 2% to 6%), as agreed between the Government and RBI.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00083', 'insurance-exam-bank', 'Banking & Financial Awareness', 1, 10, 'What is a ''Non-Performing Asset'' (NPA) in banking?', 'An NPA is a loan or advance where the **principal or interest payment has remained overdue for a period of more than 90 days**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00084', 'insurance-exam-bank', 'Banking & Financial Awareness', 1, 11, 'What is the difference between ''Gross NPA'' and ''Net NPA''?', '**Gross NPA** is the total value of all non-performing loans on a bank''s books before any provisioning.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00085', 'insurance-exam-bank', 'Banking & Financial Awareness', 1, 12, 'What is ''priority sector lending'' (PSL) in Indian banking?', 'Priority sector lending mandates that banks direct a prescribed share of their credit to sectors of national importance — **agriculture, micro/small enterprises, export credit, education, housing, and weaker sections** — as part of RBI''s financial inclusion policy.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00086', 'insurance-exam-bank', 'Banking & Financial Awareness', 1, 13, 'What is the Deposit Insurance and Credit Guarantee Corporation (DICGC), and what is its current insurance cover?', 'DICGC is a wholly-owned subsidiary of the RBI that insures **bank deposits** (savings, current, fixed, recurring) up to a limit per depositor per bank.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00087', 'insurance-exam-bank', 'Banking & Financial Awareness', 1, 14, 'What is NABARD, and what is its primary mandate?', 'NABARD (**National Bank for Agriculture and Rural Development**) was established in **1982** as an apex development bank to provide and regulate **credit for agriculture and rural development**, supporting cooperative banks, regional rural banks, and rural infrastructure.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00088', 'insurance-exam-bank', 'Banking & Financial Awareness', 1, 15, 'What is SIDBI, and what is its focus area?', 'SIDBI (**Small Industries Development Bank of India**) was established in **1990** as the principal financial institution for the **promotion, financing, and development of Micro, Small and Medium Enterprises (MSMEs)** in India.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00089', 'insurance-exam-bank', 'Banking & Financial Awareness', 1, 16, 'What is the EXIM Bank of India?', 'The Export-Import Bank of India (EXIM Bank), established in **1982**, is a specialised financial institution that provides **financial assistance to exporters and importers**, promoting India''s international trade.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00090', 'insurance-exam-bank', 'Banking & Financial Awareness', 1, 17, 'What are ''Regional Rural Banks'' (RRBs)?', 'RRBs were established under the **RRB Act, 1976** to provide banking and credit facilities specifically for **agriculture and rural development**, with ownership jointly held by the Central Government, a sponsor public sector bank, and the respective State Government.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00091', 'insurance-exam-bank', 'Banking & Financial Awareness', 1, 18, 'What is the difference between a ''Scheduled'' and a ''Non-Scheduled'' bank?', 'A **Scheduled bank** is one included in the **Second Schedule of the RBI Act, 1934**, meeting specified criteria, and is eligible for RBI facilities like loans at bank rate and membership in the clearing house.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00092', 'insurance-exam-bank', 'Banking & Financial Awareness', 1, 19, 'What is a ''Payments Bank'', and what restriction applies to it?', 'A Payments Bank is a differentiated bank licensed by the RBI that can accept deposits and offer payments/remittance services but **cannot issue loans or credit cards**, and must invest at least 75% of its deposits in government securities.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00093', 'insurance-exam-bank', 'Banking & Financial Awareness', 1, 20, 'What is a ''Small Finance Bank'' (SFB)?', 'A Small Finance Bank is a niche bank licensed to provide **basic banking and credit services to underserved sections** such as small farmers, micro and small industries, and unorganised sector entities, with priority sector lending obligations higher than universal banks.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00094', 'insurance-exam-bank', 'Banking & Financial Awareness', 1, 21, 'What is the NPCI, and name two payment systems it operates.', 'NPCI (**National Payments Corporation of India**) is an umbrella organisation that operates India''s retail payment and settlement systems.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00095', 'insurance-exam-bank', 'Banking & Financial Awareness', 1, 22, 'What is the difference between NEFT, RTGS, and IMPS?', '**NEFT (National Electronic Funds Transfer)** settles transactions in half-hourly batches, with no minimum/maximum transfer limit.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00096', 'insurance-exam-bank', 'Banking & Financial Awareness', 1, 23, 'What is UPI (Unified Payments Interface)?', 'UPI is a **real-time payment system developed by NPCI** that allows instant transfer of funds between bank accounts using a mobile application, via a single Virtual Payment Address (VPA), without needing bank account details for each transaction.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00097', 'insurance-exam-bank', 'Banking & Financial Awareness', 1, 24, 'What is the Basel III framework in banking?', 'Basel III is a set of **internationally agreed banking regulations** developed by the Basel Committee on Banking Supervision (BCBS) in response to the 2008 financial crisis, prescribing stronger capital adequacy, leverage, and liquidity requirements for banks, including a minimum **Capital to Risk-weighted Assets Ratio (CRAR)**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00098', 'insurance-exam-bank', 'Banking & Financial Awareness', 1, 25, 'What is CRAR (Capital Adequacy Ratio) in banking?', 'CRAR (Capital to Risk-weighted Assets Ratio) measures a **bank''s available capital as a percentage of its risk-weighted credit exposures**, indicating its ability to absorb losses.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00099', 'insurance-exam-bank', 'Banking & Financial Awareness', 1, 26, 'What is the function of the Securities and Exchange Board of India (SEBI)?', 'SEBI, established under the **SEBI Act, 1992**, is the statutory regulator for India''s **securities and capital markets**, responsible for protecting investor interests, regulating stock exchanges, mutual funds, and intermediaries, and preventing fraudulent trade practices.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00100', 'insurance-exam-bank', 'Banking & Financial Awareness', 1, 27, 'What is a ''mutual fund''?', 'A mutual fund is an investment vehicle that **pools money from multiple investors** and invests it in a diversified portfolio of stocks, bonds, or other securities, managed by professional fund managers, regulated in India by **SEBI**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00101', 'insurance-exam-bank', 'Banking & Financial Awareness', 1, 28, 'What is a ''credit rating agency'', and name two operating in India.', 'A credit rating agency assesses and assigns a **rating reflecting the creditworthiness** of a borrower (company, government, or financial instrument), helping investors gauge default risk.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00102', 'insurance-exam-bank', 'Banking & Financial Awareness', 1, 29, 'What is the ''Goods and Services Tax'' (GST), and when was it implemented in India?', 'GST is a **single, comprehensive indirect tax** levied on the supply of goods and services across India, replacing a host of earlier indirect taxes (excise, VAT, service tax).
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00103', 'insurance-exam-bank', 'Banking & Financial Awareness', 1, 30, 'What are the components of GST in India?', 'GST in India has three main components:
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00104', 'insurance-exam-bank', 'Banking & Financial Awareness', 1, 31, 'What is ''fiscal deficit''?', 'Fiscal deficit is the **difference between the government''s total expenditure and its total revenue (excluding borrowings)** in a financial year, indicating how much the government needs to borrow to meet its spending.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00105', 'insurance-exam-bank', 'Banking & Financial Awareness', 1, 32, 'What is the difference between ''CPI'' and ''WPI'' as inflation indices?', '**CPI (Consumer Price Index)** measures changes in the **retail prices** of a fixed basket of goods and services consumed by households, and is the index RBI targets for monetary policy.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00106', 'insurance-exam-bank', 'Banking & Financial Awareness', 1, 33, 'What is the Finance Commission of India?', 'The Finance Commission is a **constitutional body (Article 280)** constituted every five years by the President to recommend the **distribution of tax revenues between the Centre and the States**, and among the States themselves, along with grants-in-aid.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00107', 'insurance-exam-bank', 'Banking & Financial Awareness', 1, 34, 'What is NITI Aayog?', 'NITI Aayog (**National Institution for Transforming India**) is the **policy think tank of the Government of India**, established in **2015** replacing the Planning Commission, responsible for strategic and long-term policy planning without allocating government funds directly.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00108', 'insurance-exam-bank', 'Banking & Financial Awareness', 1, 35, 'What is a ''Non-Banking Financial Company'' (NBFC)?', 'An NBFC is a company registered under the Companies Act that engages in financial activities like **lending, investment, and asset financing** but does not hold a full banking license — meaning it cannot accept demand deposits or issue cheques drawn on itself, and is regulated by the RBI.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00109', 'insurance-exam-bank', 'Banking & Financial Awareness', 1, 36, 'What is the difference between a ''Current Account'' and a ''Savings Account''?', 'A **Savings Account** is meant for individuals to save money and earn interest, usually with restrictions on the number of withdrawals.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00110', 'insurance-exam-bank', 'Banking & Financial Awareness', 1, 37, 'What is ''KYC'' in banking, and what does it stand for?', 'KYC stands for **''Know Your Customer''** — the mandatory process by which banks and financial institutions verify the **identity and address of their customers** before establishing a business relationship, to prevent fraud, money laundering, and identity theft.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00111', 'insurance-exam-bank', 'Banking & Financial Awareness', 1, 38, 'What is the ''Prevention of Money Laundering Act'' (PMLA), 2002?', 'PMLA, 2002 is a law enacted to **prevent money laundering** and to provide for confiscation of property derived from, or involved in, money laundering, and matters connected therewith; it requires banks and financial institutions to maintain KYC records and report suspicious transactions.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00112', 'insurance-exam-bank', 'Banking & Financial Awareness', 1, 39, 'What is the Insolvency and Bankruptcy Code (IBC), 2016?', 'The IBC, 2016 is a consolidated law that provides a **time-bound process for resolving insolvency** of companies, partnerships, and individuals, aiming to maximise asset value and balance the interests of all stakeholders, overseen by the **Insolvency and Bankruptcy Board of India (IBBI)**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00113', 'insurance-exam-bank', 'Banking & Financial Awareness', 1, 40, 'What is ''Jan Dhan Yojana'' (PMJDY)?', 'Pradhan Mantri Jan Dhan Yojana, launched in **2014**, is the government''s **financial inclusion** programme that provides every unbanked household access to a **basic savings bank account**, along with a RuPay debit card, accident insurance cover, and an overdraft facility.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00114', 'insurance-exam-bank', 'Banking & Financial Awareness', 1, 41, 'What is the ''Bharatiya Mahila Bank'', and what happened to it?', 'Bharatiya Mahila Bank was a public-sector bank set up in **2013** to promote women''s economic empowerment and financial inclusion; it was **merged with the State Bank of India (SBI) in 2017**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00115', 'insurance-exam-bank', 'Banking & Financial Awareness', 1, 42, 'What is the ''Banking Regulation Act, 1949'' meant to govern?', 'The Banking Regulation Act, 1949 is the primary legislation that **regulates and supervises all banking companies in India**, giving the RBI powers over licensing, branch expansion, management, and operations of banks, including cooperative banks (after later amendments).', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00116', 'insurance-exam-bank', 'Banking & Financial Awareness', 1, 43, 'What is ''demonetisation'', referring to the 2016 Indian context?', 'Demonetisation refers to the Indian government''s action on **8 November 2016**, withdrawing the legal tender status of ₹500 and ₹1,000 currency notes, aimed at curbing black money, counterfeit currency, and promoting digital payments.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00117', 'insurance-exam-bank', 'Banking & Financial Awareness', 1, 44, 'What is an ''Asset Reconstruction Company'' (ARC)?', 'An ARC is a specialised financial institution that **buys bad loans (NPAs) from banks at a discount** and tries to recover the dues from borrowers through restructuring or liquidation, functioning under the **SARFAESI Act, 2002**, regulated by the RBI.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00118', 'insurance-exam-bank', 'Banking & Financial Awareness', 1, 45, 'What is the SARFAESI Act, 2002?', 'SARFAESI stands for the **Securitisation and Reconstruction of Financial Assets and Enforcement of Security Interest Act, 2002**; it allows banks and financial institutions to **recover NPAs without court intervention** by auctioning residential/commercial properties pledged as collateral.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00119', 'insurance-exam-bank', 'Banking & Financial Awareness', 1, 46, 'What is the ''repo rate corridor'' in RBI''s Liquidity Adjustment Facility (LAF)?', 'The LAF corridor is the band formed by the **MSF rate (upper bound)** and the **Standing Deposit Facility/reverse repo rate (lower bound)**, with the **repo rate positioned in the middle**, within which short-term money market interest rates are expected to fluctuate.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00120', 'insurance-exam-bank', 'Banking & Financial Awareness', 1, 47, 'What is the ''Standing Deposit Facility'' (SDF)?', 'SDF is a tool introduced by the RBI that allows it to **absorb excess liquidity from banks without providing any collateral** in return, serving as the floor of the liquidity adjustment facility corridor, replacing the fixed-rate reverse repo for this purpose.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00121', 'insurance-exam-bank', 'Banking & Financial Awareness', 1, 48, 'What is ''Base Rate'' and how does it relate to ''MCLR''?', '**Base Rate** was the minimum lending rate below which banks could not lend, introduced in 2010.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00122', 'insurance-exam-bank', 'Banking & Financial Awareness', 1, 49, 'What is the function of the Credit Information Bureau (India) Limited (CIBIL)?', 'CIBIL is India''s first credit information company, which **collects and maintains credit records of individuals and businesses**, generating a ''CIBIL score'' (300-900) that lenders use to assess a borrower''s creditworthiness before sanctioning loans.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00123', 'insurance-exam-bank', 'Banking & Financial Awareness', 1, 50, 'What is the ''Atal Pension Yojana'' (APY)?', 'APY is a government-backed **pension scheme** targeted at workers in the unorganised sector, guaranteeing a fixed monthly pension (ranging from ₹1,000 to ₹5,000) after the age of 60, based on the contribution amount and the subscriber''s age at entry.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00124', 'insurance-exam-bank', 'Banking & Financial Awareness', 1, 51, 'What is ''Sovereign Gold Bond'' (SGB) scheme?', 'SGBs are **government securities denominated in grams of gold**, issued by the RBI on behalf of the Government of India, offering investors an alternative to holding physical gold along with a fixed annual interest rate, with returns linked to gold price movements at maturity.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00125', 'insurance-exam-bank', 'Banking & Financial Awareness', 1, 52, 'What is the ''repo-linked lending rate'' (RLLR)?', 'RLLR is a lending rate directly **benchmarked to the RBI''s repo rate**; when the repo rate changes, RLLR-linked loans (such as home loans) are adjusted accordingly, ensuring **faster transmission** of monetary policy changes to borrowers compared to MCLR-based loans.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00126', 'insurance-exam-bank', 'Banking & Financial Awareness', 1, 53, 'What does the term ''Bancassurance'' mean?', 'Bancassurance refers to the **distribution of insurance products through a bank''s network** of branches and customer base, under a tie-up between a bank and an insurance company, benefiting both parties through cross-selling.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00127', 'insurance-exam-bank', 'Banking & Financial Awareness', 1, 54, 'What is the ''Pradhan Mantri Mudra Yojana'' (PMMY)?', 'PMMY, launched in **2015**, provides **collateral-free loans up to ₹20 lakh** to non-corporate, non-farm micro and small enterprises, categorised under three loan brackets — Shishu, Kishor, and Tarun (and the higher ''Tarun Plus'' category added later).', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00128', 'insurance-exam-bank', 'Banking & Financial Awareness', 1, 55, 'What is the role of the ''Appointed Actuary'' in an Indian insurance company?', 'The Appointed Actuary is a senior actuarial professional, mandated by IRDAI in every insurance company, responsible for ensuring the **adequacy of reserves, soundness of premium rates, and overall financial health** of the insurer, reporting both to the company''s board and to the regulator.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00129', 'insurance-exam-bank', 'Banking & Financial Awareness', 1, 56, 'What is ''Direct Benefit Transfer'' (DBT)?', 'DBT is a government mechanism to **transfer subsidies and welfare scheme benefits directly into beneficiaries'' bank accounts**, reducing leakages and delays by cutting out intermediaries, enabled by the Jan Dhan-Aadhaar-Mobile (JAM) trinity.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00130', 'insurance-exam-bank', 'Banking & Financial Awareness', 1, 57, 'What is the ''JAM Trinity''?', 'JAM Trinity refers to the linkage of **Jan Dhan bank accounts, Aadhaar unique identity numbers, and Mobile phone numbers**, used by the government to ensure targeted, leak-proof, and efficient delivery of subsidies and benefits directly to citizens.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00131', 'insurance-exam-bank', 'Banking & Financial Awareness', 1, 58, 'What is ''Financial Inclusion'', in the Indian banking policy context?', 'Financial inclusion refers to the process of ensuring **access to formal financial services** — banking, credit, insurance, and pension products — at an affordable cost to all sections of society, especially the economically weaker and rural populations.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00132', 'insurance-exam-bank', 'Banking & Financial Awareness', 1, 59, 'What is a ''Certificate of Deposit'' (CD)?', 'A Certificate of Deposit is a **negotiable, unsecured money market instrument** issued by banks and select financial institutions in dematerialised form, against funds deposited for a fixed period, usually in large denominations for institutional investors.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00133', 'insurance-exam-bank', 'Banking & Financial Awareness', 1, 60, 'What is a ''Commercial Paper'' (CP)?', 'Commercial Paper is a **short-term, unsecured promissory note** issued by highly-rated corporates, primary dealers, and financial institutions to raise working capital funds directly from the money market, rather than through bank loans.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00134', 'insurance-exam-bank', 'Banking & Financial Awareness', 1, 61, 'What is the ''repo rate'' used for by RBI with regard to inflation targeting?', 'The repo rate is the key **policy instrument** the RBI''s Monetary Policy Committee uses to steer inflation towards its target: it is raised to tighten liquidity and cool demand-driven inflation, and lowered to spur growth when inflation is under control.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00135', 'insurance-exam-bank', 'Banking & Financial Awareness', 1, 62, 'What is a ''Primary Market'' versus a ''Secondary Market'' in the context of securities?', 'The **Primary Market** is where new securities (shares, bonds) are issued for the first time directly by the issuer to investors (e.g., an IPO).
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00136', 'insurance-exam-bank', 'Banking & Financial Awareness', 1, 63, 'What are the two main stock exchanges in India?', 'The two principal stock exchanges in India are the **Bombay Stock Exchange (BSE)**, Asia''s oldest stock exchange (established 1875), and the **National Stock Exchange (NSE)**, established in 1992, known for its benchmark index, the Nifty 50.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00137', 'insurance-exam-bank', 'Banking & Financial Awareness', 1, 64, 'What is an ''Initial Public Offering'' (IPO)?', 'An IPO is the process by which a **private company offers its shares to the public for the first time**, converting itself into a publicly listed company, in order to raise capital from a wide base of investors.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00138', 'insurance-exam-bank', 'Banking & Financial Awareness', 1, 65, 'What is the difference between a ''Bull Market'' and a ''Bear Market''?', 'A **Bull Market** is a period of **sustained rising prices** and investor optimism in financial markets.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00139', 'insurance-exam-bank', 'Banking & Financial Awareness', 1, 66, 'What is ''repo'' derived from, and what collateral is typically used in RBI''s repo operations?', '''Repo'' is short for **''Repurchase Agreement''** — a short-term borrowing arrangement where a bank sells government securities to the RBI with an agreement to repurchase them at a predetermined price and date, with **government securities (G-Secs)** serving as the collateral.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00140', 'insurance-exam-bank', 'Banking & Financial Awareness', 1, 67, 'What is ''Angel Tax'' in the Indian startup/finance context?', 'Angel Tax refers to the tax levied (under Section 56(2)(viib) of the Income Tax Act) on the **share premium received by unlisted companies (including startups) that exceeds the fair market value** of shares issued, when raised from resident investors.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00141', 'insurance-exam-bank', 'Banking & Financial Awareness', 1, 68, 'What is the function of the ''Pension Fund Regulatory and Development Authority'' (PFRDA)?', 'PFRDA, established under the **PFRDA Act, 2013**, is the statutory regulator that **regulates and develops the pension sector in India**, including the National Pension System (NPS) and Atal Pension Yojana, to protect the interests of subscribers.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00142', 'insurance-exam-bank', 'Banking & Financial Awareness', 1, 69, 'What is the National Pension System (NPS)?', 'NPS is a **voluntary, defined-contribution pension scheme** open to all Indian citizens, under which subscribers build a retirement corpus through regular contributions invested across equity, corporate debt, and government securities, regulated by PFRDA.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00143', 'insurance-exam-bank', 'Banking & Financial Awareness', 1, 70, 'What is ''Bank Rate Policy'' and how is the Bank Rate different from the repo rate today?', 'Historically, Bank Rate was RBI''s main policy tool; today it is **aligned with the MSF rate** and mainly used to determine penal interest for banks that default on CRR/SLR requirements, while the **repo rate** remains the operative tool for day-to-day liquidity management and signalling monetary policy stance.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00144', 'insurance-exam-bank', 'Banking & Financial Awareness', 1, 71, 'What is a ''Systemically Important Bank'' or D-SIB in India?', 'A Domestic Systemically Important Bank (D-SIB) is a bank whose **failure could significantly disrupt the broader financial system and economy** due to its size, complexity, and interconnectedness; such banks (e.g., SBI, HDFC Bank, ICICI Bank) are subject to additional capital surcharge requirements by the RBI.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00145', 'insurance-exam-bank', 'Quantitative Aptitude', 2, 0, 'If the simple interest on a sum for 2 years at 10% per annum is ₹400, find the sum.', 'Simple interest formula: `SI = (P × R × T) / 100`.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00146', 'insurance-exam-bank', 'Quantitative Aptitude', 2, 1, 'Find the compound interest on ₹10,000 for 2 years at 10% per annum, compounded annually.', 'Amount formula: `A = P(1 + R/100)^T = 10000 × (1.1)^2 = 10000 × 1.21 = 12100`.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00147', 'insurance-exam-bank', 'Quantitative Aptitude', 2, 2, 'A sum amounts to ₹2,420 in 2 years and ₹2,662 in 3 years at compound interest. Find the rate of interest.', 'The interest for the third year alone is `2662 − 2420 = 242`, earned on the principal-equivalent of ₹2,420.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00148', 'insurance-exam-bank', 'Quantitative Aptitude', 2, 3, 'A shopkeeper marks an article at ₹800 and offers a discount of 15%. Find the selling price.', 'Discount amount `= 15% of 800 = 0.15 × 800 = 120`.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00149', 'insurance-exam-bank', 'Quantitative Aptitude', 2, 4, 'An item is bought for ₹1,200 and sold for ₹1,500. Find the profit percentage.', 'Profit `= 1500 − 1200 = 300`.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00150', 'insurance-exam-bank', 'Quantitative Aptitude', 2, 5, 'A trader sells an article at a loss of 20% for ₹960. Find its cost price.', 'Let cost price be `CP`. Since selling at a loss of 20% means `SP = 0.8 × CP`.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00151', 'insurance-exam-bank', 'Quantitative Aptitude', 2, 6, 'Find the single discount equivalent to two successive discounts of 20% and 10%.', 'Net price factor `= (1 − 0.20) × (1 − 0.10) = 0.8 × 0.9 = 0.72`.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00152', 'insurance-exam-bank', 'Quantitative Aptitude', 2, 7, 'In what ratio must rice at ₹40/kg be mixed with rice at ₹60/kg so that the mixture costs ₹48/kg?', 'Using the rule of alligation, the ratio of cheaper to dearer quantity is `(60 − 48) : (48 − 40) = 12 : 8 = 3 : 2`.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00153', 'insurance-exam-bank', 'Quantitative Aptitude', 2, 8, 'The average of 5 numbers is 20. If one number is excluded, the average becomes 18. Find the excluded number.', 'Sum of 5 numbers `= 5 × 20 = 100`.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00154', 'insurance-exam-bank', 'Quantitative Aptitude', 2, 9, 'The average age of a class of 30 students is 12 years. If the teacher''s age (40 years) is included, find the new average.', 'Total age of 30 students `= 30 × 12 = 360`.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00155', 'insurance-exam-bank', 'Quantitative Aptitude', 2, 10, 'A can do a piece of work in 10 days and B can do it in 15 days. In how many days will they finish it together?', 'A''s one-day work `= 1/10`, B''s one-day work `= 1/15`.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00156', 'insurance-exam-bank', 'Quantitative Aptitude', 2, 11, 'A and B together can complete a job in 12 days. A alone can do it in 20 days. In how many days can B alone complete it?', 'Combined one-day work `= 1/12`. A''s one-day work `= 1/20`.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00157', 'insurance-exam-bank', 'Quantitative Aptitude', 2, 12, 'A tap can fill a tank in 6 hours, and another tap can empty it in 9 hours. If both are opened together, in how long will the tank be filled?', 'Filling rate `= 1/6` per hour, emptying rate `= 1/9` per hour.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00158', 'insurance-exam-bank', 'Quantitative Aptitude', 2, 13, 'A train 150 m long crosses a pole in 15 seconds. Find its speed in km/h.', 'Speed `= distance / time = 150 / 15 = 10` m/s.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00159', 'insurance-exam-bank', 'Quantitative Aptitude', 2, 14, 'A train 200 m long running at 72 km/h crosses a platform in 25 seconds. Find the length of the platform.', 'Speed in m/s `= 72 × 5/18 = 20` m/s.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00160', 'insurance-exam-bank', 'Quantitative Aptitude', 2, 15, 'A man rows 15 km downstream in 3 hours and the same distance upstream in 5 hours. Find the speed of the stream.', 'Downstream speed `= 15/3 = 5` km/h. Upstream speed `= 15/5 = 3` km/h.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00161', 'insurance-exam-bank', 'Quantitative Aptitude', 2, 16, 'Two trains of lengths 120 m and 180 m run towards each other at 54 km/h and 36 km/h respectively. Find the time taken to cross each other.', 'Relative speed (opposite directions) `= 54 + 36 = 90` km/h `= 90 × 5/18 = 25` m/s.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00162', 'insurance-exam-bank', 'Quantitative Aptitude', 2, 17, 'The ages of A and B are in the ratio 3:4. After 5 years, the ratio becomes 4:5. Find A''s present age.', 'Let the present ages be `3x` and `4x`.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00163', 'insurance-exam-bank', 'Quantitative Aptitude', 2, 18, 'The sum of the present ages of a father and son is 60 years. Six years ago, the father''s age was five times the son''s age. Find the son''s present age.', 'Let the son''s present age be `s`, so the father''s present age `= 60 − s`.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00164', 'insurance-exam-bank', 'Quantitative Aptitude', 2, 19, 'Two numbers are in the ratio 5:7. If their sum is 108, find the two numbers.', 'Let the numbers be `5x` and `7x`, so `5x + 7x = 108`, giving `12x = 108`, so `x = 9`.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00165', 'insurance-exam-bank', 'Quantitative Aptitude', 2, 20, 'Divide ₹2,400 among A, B, and C in the ratio 2:3:5.', 'Total parts `= 2 + 3 + 5 = 10`.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00166', 'insurance-exam-bank', 'Quantitative Aptitude', 2, 21, 'A and B start a business with investments of ₹4,000 and ₹6,000. If the annual profit is ₹5,000, find A''s share.', 'Profit-sharing ratio equals the investment ratio (same duration): `4000 : 6000 = 2 : 3`.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00167', 'insurance-exam-bank', 'Quantitative Aptitude', 2, 22, 'A invests ₹3,000 for the full year, and B invests ₹4,500 for 8 months. Find the profit-sharing ratio.', 'A''s capital-months `= 3000 × 12 = 36000`. B''s capital-months `= 4500 × 8 = 36000`.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00168', 'insurance-exam-bank', 'Quantitative Aptitude', 2, 23, 'Find the value of x: `(3/4) × x = 45`.', '`x = 45 ÷ (3/4) = 45 × (4/3) = 60`.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00169', 'insurance-exam-bank', 'Quantitative Aptitude', 2, 24, 'Simplify: `(25 × 4) + (18 ÷ 3) − 12`.', '`25 × 4 = 100`. `18 ÷ 3 = 6`.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00170', 'insurance-exam-bank', 'Quantitative Aptitude', 2, 25, 'If 20% of a number is 50, find the number.', 'Let the number be `x`. Then `0.20 × x = 50`, so `x = 50 / 0.20 = 250`.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00171', 'insurance-exam-bank', 'Quantitative Aptitude', 2, 26, 'A''s salary is increased by 20% and then decreased by 20%. Find the net percentage change.', 'Net factor `= (1 + 0.20) × (1 − 0.20) = 1.2 × 0.8 = 0.96`.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00172', 'insurance-exam-bank', 'Quantitative Aptitude', 2, 27, 'In an election between two candidates, the winner got 60% of votes and won by 1,200 votes. Find the total number of votes polled.', 'Winner''s share `= 60%`, loser''s share `= 40%`, so the winning margin `= 20%` of total votes.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00173', 'insurance-exam-bank', 'Quantitative Aptitude', 2, 28, 'Find the probability of getting a sum of 7 when two dice are thrown together.', 'Total outcomes when two dice are thrown `= 6 × 6 = 36`.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00174', 'insurance-exam-bank', 'Quantitative Aptitude', 2, 29, 'A bag contains 5 red balls and 3 blue balls. Find the probability of drawing one red ball at random.', 'Total balls `= 5 + 3 = 8`.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00175', 'insurance-exam-bank', 'Quantitative Aptitude', 2, 30, 'In how many ways can the letters of the word ''BANK'' be arranged?', 'The word ''BANK'' has 4 distinct letters.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00176', 'insurance-exam-bank', 'Quantitative Aptitude', 2, 31, 'In how many ways can a committee of 3 people be chosen from a group of 7 people?', 'This is a combination problem: `C(7,3) = 7! / (3! × 4!) = (7 × 6 × 5) / (3 × 2 × 1) = 210 / 6 = 35`.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00177', 'insurance-exam-bank', 'Quantitative Aptitude', 2, 32, 'Find the next number in the series: 2, 6, 12, 20, 30, ?', 'The differences between consecutive terms are `4, 6, 8, 10`, increasing by 2 each time.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00178', 'insurance-exam-bank', 'Quantitative Aptitude', 2, 33, 'Find the missing number in the series: 3, 9, 27, 81, ?', 'Each term is obtained by multiplying the previous term by **3** (a geometric progression).
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00179', 'insurance-exam-bank', 'Quantitative Aptitude', 2, 34, 'Find the wrong number in the series: 5, 10, 17, 26, 37, 51.', 'The expected differences follow the pattern `+5, +7, +9, +11, +13` (odd numbers increasing by 2), since the series follows `n² + 1`: 5, 10, 17, 26, 37, **50**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00180', 'insurance-exam-bank', 'Quantitative Aptitude', 2, 35, 'A sum of money doubles itself in 8 years at simple interest. Find the rate of interest.', 'If the sum doubles, the interest earned equals the principal itself, i.e., `SI = P` over `T = 8` years.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00181', 'insurance-exam-bank', 'Quantitative Aptitude', 2, 36, 'The length of a rectangle is 15 m and its breadth is 8 m. Find its area and perimeter.', 'Area `= length × breadth = 15 × 8 = 120` sq. m.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00182', 'insurance-exam-bank', 'Quantitative Aptitude', 2, 37, 'Find the area of a circle with radius 7 cm (use π = 22/7).', 'Area `= π × r² = (22/7) × 7 × 7 = 22 × 7 = 154` sq. cm.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00183', 'insurance-exam-bank', 'Quantitative Aptitude', 2, 38, 'Find the volume of a cube with side 5 cm.', 'Volume of a cube `= side³ = 5 × 5 × 5 = 125` cubic cm.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00184', 'insurance-exam-bank', 'Quantitative Aptitude', 2, 39, 'Find the curved surface area of a cylinder with radius 7 cm and height 10 cm (use π = 22/7).', 'Curved surface area `= 2πrh = 2 × (22/7) × 7 × 10 = 2 × 22 × 10 = 440` sq. cm.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00185', 'insurance-exam-bank', 'Quantitative Aptitude', 2, 40, 'A sum of ₹8,000 becomes ₹9,261 in 3 years at a certain rate of compound interest, compounded annually. Find the rate.', 'Using `A = P(1+R/100)^3`: `9261/8000 = (1+R/100)^3`.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00186', 'insurance-exam-bank', 'Quantitative Aptitude', 2, 41, 'Find the HCF and LCM of 12 and 18.', 'Factors: `12 = 2² × 3` and `18 = 2 × 3²`.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00187', 'insurance-exam-bank', 'Quantitative Aptitude', 2, 42, 'The HCF and LCM of two numbers are 4 and 48 respectively. If one number is 16, find the other.', 'Product of two numbers `= HCF × LCM = 4 × 48 = 192`.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00188', 'insurance-exam-bank', 'Quantitative Aptitude', 2, 43, 'If the cost price of 12 articles equals the selling price of 10 articles, find the profit percentage.', 'Let the cost price of 1 article be `1` unit, so cost price of 10 articles `= 10` units, and this equals the selling price of 10 articles (given to equal cost price of 12 articles `= 12` units).
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00189', 'insurance-exam-bank', 'Quantitative Aptitude', 2, 44, 'A man covers a distance of 300 km in 5 hours partly by car at 80 km/h and partly by bike at 40 km/h. Find the distance covered by car.', 'Let the distance by car be `x` km, so distance by bike `= 300 − x` km.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00190', 'insurance-exam-bank', 'Quantitative Aptitude', 2, 45, 'A sum is divided between A and B such that A''s share is to B''s share as 3:5. If B''s share is ₹2,500, find A''s share.', 'Let A''s share `= 3x` and B''s share `= 5x`.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00191', 'insurance-exam-bank', 'Quantitative Aptitude', 2, 46, 'A alone can complete a work in 18 days. He works for 6 days and then B completes the remaining work in 8 days. In how many days can B alone complete the whole work?', 'A''s one-day work `= 1/18`. Work done by A in 6 days `= 6/18 = 1/3`.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00192', 'insurance-exam-bank', 'Quantitative Aptitude', 2, 47, 'A boat''s speed in still water is 10 km/h and the speed of the stream is 2 km/h. Find the time taken to cover 36 km downstream.', 'Downstream speed `= boat speed + stream speed = 10 + 2 = 12` km/h.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00193', 'insurance-exam-bank', 'Quantitative Aptitude', 2, 48, 'A sum of money becomes 3 times itself in 20 years at simple interest. Find the rate of interest.', 'If the sum becomes 3 times, the interest earned equals twice the principal, i.e., `SI = 2P`, over `T = 20` years.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00194', 'insurance-exam-bank', 'Quantitative Aptitude', 2, 49, 'Find the average of the first 10 natural numbers.', 'Sum of first 10 natural numbers `= n(n+1)/2 = 10 × 11/2 = 55`.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00195', 'insurance-exam-bank', 'Quantitative Aptitude', 2, 50, 'A can complete a task in 12 days, while B is 20% more efficient than A. Find the number of days B takes to complete the same task.', 'If B is 20% more efficient, B''s work rate is `1.2` times A''s rate.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00196', 'insurance-exam-bank', 'Quantitative Aptitude', 2, 51, 'Find the compound interest on ₹5,000 for 1 year at 10% per annum, compounded half-yearly.', 'For half-yearly compounding, rate per period `= 5%`, and number of periods `= 2`.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00197', 'insurance-exam-bank', 'Quantitative Aptitude', 2, 52, 'A sells an article to B at a profit of 10%, and B sells it to C at a profit of 20%. If C pays ₹1,320, find the original cost price to A.', 'Let the cost price to A be `CP`.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00198', 'insurance-exam-bank', 'Quantitative Aptitude', 2, 53, 'The ratio of the ages of two brothers is 4:5, and the sum of their ages is 36 years. Find their ages.', 'Let the ages be `4x` and `5x`, so `4x + 5x = 36`, giving `9x = 36`, so `x = 4`.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00199', 'insurance-exam-bank', 'Quantitative Aptitude', 2, 54, 'If 15 workers can complete a job in 8 days, how many days will 20 workers take to complete the same job?', 'Total work (in worker-days) `= 15 × 8 = 120`.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00200', 'insurance-exam-bank', 'Quantitative Aptitude', 2, 55, 'Find the simple interest on ₹15,000 at 8% per annum for 3 years.', '`SI = (P × R × T)/100 = (15000 × 8 × 3)/100 = 360000/100 = 3600`.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00201', 'insurance-exam-bank', 'Quantitative Aptitude', 2, 56, 'A number, when increased by 25%, becomes 125. Find the original number.', 'Let the original number be `x`, so `1.25x = 125`, giving `x = 125/1.25 = 100`.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00202', 'insurance-exam-bank', 'Quantitative Aptitude', 2, 57, 'Two pipes A and B can fill a tank in 20 minutes and 30 minutes respectively. If both pipes are opened together, find the time taken to fill the tank.', 'A''s rate `= 1/20`, B''s rate `= 1/30` per minute.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00203', 'insurance-exam-bank', 'Quantitative Aptitude', 2, 58, 'A train covers 300 km at a uniform speed. If the speed had been 10 km/h more, it would have taken 1 hour less. Find the original speed.', 'Let the original speed be `s` km/h, so time taken `= 300/s`.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00204', 'insurance-exam-bank', 'Quantitative Aptitude', 2, 59, 'Find the value of x if the ratio 2:3 is equivalent to x:36.', 'Setting up the proportion: `2/3 = x/36`.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00205', 'insurance-exam-bank', 'Quantitative Aptitude', 2, 60, 'A invests ₹10,000 in a business, and B joins 4 months later with ₹15,000. Find the ratio of their profits at the end of the year.', 'A''s capital-months `= 10000 × 12 = 120000`.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00206', 'insurance-exam-bank', 'Quantitative Aptitude', 2, 61, 'A, B, and C can complete a work in 10, 15, and 30 days respectively. Find the number of days they will take to complete it working together.', 'A''s rate `= 1/10`, B''s rate `= 1/15`, C''s rate `= 1/30`.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00207', 'insurance-exam-bank', 'Quantitative Aptitude', 2, 62, 'A man''s income is increased by ₹2,000, which represents a 10% increase. Find his original income.', 'Let original income be `x`. Then `10% of x = 2000`, so `x = 2000/0.10 = 20000`.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00208', 'insurance-exam-bank', 'Quantitative Aptitude', 2, 63, 'Find the discount percentage if an article marked at ₹2,000 is sold for ₹1,700.', 'Discount amount `= 2000 − 1700 = 300`.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00209', 'insurance-exam-bank', 'Quantitative Aptitude', 2, 64, 'If the ratio of boys to girls in a class of 45 is 4:5, find the number of girls.', 'Total parts `= 4 + 5 = 9`.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00210', 'insurance-exam-bank', 'Quantitative Aptitude', 2, 65, 'A alone can finish a work in 15 days and B alone in 10 days. They work together for 3 days, after which A leaves. In how many more days will B finish the remaining work?', 'Combined one-day work `= 1/15 + 1/10 = 2/30 + 3/30 = 5/30 = 1/6`.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00211', 'insurance-exam-bank', 'Quantitative Aptitude', 2, 66, 'Find the compound interest on ₹20,000 for 3 years at 10% per annum (compounded annually), to the nearest rupee.', 'Amount `= 20000 × (1.1)^3 = 20000 × 1.331 = 26620`.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00212', 'insurance-exam-bank', 'Quantitative Aptitude', 2, 67, 'If A''s income is 25% more than B''s income, by what percentage is B''s income less than A''s?', 'Let B''s income `= 100`, so A''s income `= 125`.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00213', 'insurance-exam-bank', 'Quantitative Aptitude', 2, 68, 'A shopkeeper allows a 10% discount on the marked price and still makes a profit of 17%. If the cost price is ₹500, find the marked price.', 'Selling price `= CP × 1.17 = 500 × 1.17 = 585`.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00214', 'insurance-exam-bank', 'Quantitative Aptitude', 2, 69, 'Two numbers are in the ratio 4:5. If 30 is subtracted from each, the ratio becomes 1:2. Find the numbers.', 'Let the numbers be `4x` and `5x`.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00215', 'insurance-exam-bank', 'Quantitative Aptitude', 2, 70, 'A, B, and C invest ₹5,000, ₹8,000, and ₹7,000 respectively in a business for one year. If the total profit is ₹4,000, find C''s share.', 'Total investment `= 5000 + 8000 + 7000 = 20000`.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00216', 'insurance-exam-bank', 'Reasoning Ability', 3, 0, 'In a certain code, ''CAT'' is written as ''DBU''. How is ''DOG'' written in that code?', 'Each letter in the code is shifted **one step forward** in the alphabet: C→D, A→B, T→U.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00217', 'insurance-exam-bank', 'Reasoning Ability', 3, 1, 'If A is the brother of B, and B is the sister of C, and C is the father of D, how is A related to D?', 'B is the sister of C, and C is the father of D, so B is D''s **aunt or uncle** (specifically aunt, since B is female).
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00218', 'insurance-exam-bank', 'Reasoning Ability', 3, 2, 'Pointing to a photograph, a man said, "She is the daughter of my grandfather''s only son." How is the woman related to the man?', 'The man''s grandfather''s only son is the man''s **father** (since the grandfather has only one son).
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00219', 'insurance-exam-bank', 'Reasoning Ability', 3, 3, 'Rahul walks 5 km to the east, then turns left and walks 3 km, then turns left again and walks 5 km. How far is he from his starting point, and in which direction?', 'Rahul''s path: east 5 km, then left (north) 3 km, then left again (west) 5 km.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00220', 'insurance-exam-bank', 'Reasoning Ability', 3, 4, 'In a row of children, Meena is 7th from the left and 12th from the right. How many children are there in the row?', 'Total children `= (position from left) + (position from right) − 1 = 7 + 12 − 1 = 18`.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00221', 'insurance-exam-bank', 'Reasoning Ability', 3, 5, 'Find the odd one out: Apple, Mango, Potato, Banana.', 'Apple, Mango, and Banana are all **fruits**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00222', 'insurance-exam-bank', 'Reasoning Ability', 3, 6, 'Find the odd one out: Triangle, Square, Circle, Cube.', 'Triangle, Square, and Circle are all **two-dimensional (2D) shapes**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00223', 'insurance-exam-bank', 'Reasoning Ability', 3, 7, 'Complete the analogy: Doctor is to Hospital as Teacher is to ____.', 'A Doctor''s typical workplace is a **Hospital**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00224', 'insurance-exam-bank', 'Reasoning Ability', 3, 8, 'Complete the analogy: Pen is to Write as Knife is to ____.', 'A Pen is used to **Write** (its primary function).
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00225', 'insurance-exam-bank', 'Reasoning Ability', 3, 9, 'If ''A'' means ''+'', ''B'' means ''−'', ''C'' means ''×'', and ''D'' means ''÷'', evaluate: 10 A 5 C 2 B 4.', 'Substituting symbols: `10 + 5 × 2 − 4`.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00226', 'insurance-exam-bank', 'Reasoning Ability', 3, 10, 'Arrange the words in a meaningful order: 1. Word 2. Sentence 3. Letter 4. Paragraph 5. Phrase.', 'The logical order of increasing size of a language unit is: a single **Letter** combines to form a **Word**, words combine into a **Phrase**, phrases extend into a **Sentence**, and sentences combine to form a **Paragraph**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00227', 'insurance-exam-bank', 'Reasoning Ability', 3, 11, 'In a certain code, ''FRIEND'' is written as ''EQHDMC''. How would ''CANDLE'' be written in the same code?', 'Each letter in the code is shifted **one step backward** in the alphabet: F→E, R→Q, I→H, E→D, N→M, D→C.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00228', 'insurance-exam-bank', 'Reasoning Ability', 3, 12, 'If Monday falls on the 1st of a month, what day of the week will the 29th of that month be?', 'From the 1st to the 29th is a difference of `29 − 1 = 28` days, and `28` is exactly divisible by 7 (`28 = 4 × 7`).
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00229', 'insurance-exam-bank', 'Reasoning Ability', 3, 13, 'At what angle do the hour and minute hands of a clock make at 3:00?', 'At 3:00, the minute hand points at 12, and the hour hand points at 3.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00230', 'insurance-exam-bank', 'Reasoning Ability', 3, 14, 'How many times do the hour and minute hands of a clock overlap in a 12-hour period?', 'In a 12-hour period, the hands of a clock coincide **11 times** (they would seem to coincide 12 times, but one overlap at the start and one at the end coincide at the same 12 O''clock position, so effectively 11 distinct overlaps occur).
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00231', 'insurance-exam-bank', 'Reasoning Ability', 3, 15, 'A is taller than B but shorter than C. D is taller than C. Who is the tallest?', 'From the given information: `B < A < C < D`.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00232', 'insurance-exam-bank', 'Reasoning Ability', 3, 16, 'Look at this series: 2, 4, 8, 16, ... What number comes next?', 'Each term is obtained by **multiplying the previous term by 2** (a geometric progression with common ratio 2).
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00233', 'insurance-exam-bank', 'Reasoning Ability', 3, 17, 'Look at this series: J, F, M, A, M, ... What comes next?', 'The series represents the **first letters of the months** of the year: January, February, March, April, May.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00234', 'insurance-exam-bank', 'Reasoning Ability', 3, 18, 'If South-East becomes North, North-East becomes West, what does South become?', 'Measuring each direction as an angle clockwise from North (N=0°, NE=45°, E=90°, SE=135°, S=180°, SW=225°, W=270°, NW=315°), the rule maps South-East (135°) to North (0°), a shift of **+225°** (i.e., −135°).
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00235', 'insurance-exam-bank', 'Reasoning Ability', 3, 19, 'Statement: All pens are books. All books are tables. Conclusion I: All pens are tables. Conclusion II: All tables are pens. Which conclusion(s) follow?', 'Since all pens are books, and all books are tables, it logically follows that **all pens are tables** (Conclusion I follows, by the transitive property of a universal syllogism).
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00236', 'insurance-exam-bank', 'Reasoning Ability', 3, 20, 'Statement: Some doctors are engineers. All engineers are scientists. Conclusion I: Some doctors are scientists. Conclusion II: All scientists are engineers.', 'Since some doctors are engineers, and all engineers are scientists, those doctors who are engineers must also be scientists, so **some doctors are scientists** follows (Conclusion I is valid).
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00237', 'insurance-exam-bank', 'Reasoning Ability', 3, 21, 'In a family of six members, P is the father of Q. Q is the brother of R. R is the daughter of S, and S is the wife of P. How is P related to R?', 'S is the wife of P, and R is the daughter of S, which makes R the daughter of both S and P.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00238', 'insurance-exam-bank', 'Reasoning Ability', 3, 22, 'If ''BOOK'' is coded as ''2152511'', what is the coding logic, and how would ''PEN'' be coded similarly (using A=1, B=2, ... Z=26)?', 'Using the standard alphabet-position code (A=1, B=2 ... Z=26): B=2, O=15, O=15, K=11, giving ''2-15-15-11'', matching the pattern.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00239', 'insurance-exam-bank', 'Reasoning Ability', 3, 23, 'Five friends P, Q, R, S, and T are sitting in a row facing north. Q is to the right of P, R is to the left of P, S is to the right of Q, and T is to the left of R. What is the order from left to right?', 'Building step by step: R is left of P, so order so far is R, P. Q is right of P: R, P, Q. S is right of Q: R, P, Q, S. T is left of R: T, R, P, Q, S.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00240', 'insurance-exam-bank', 'Reasoning Ability', 3, 24, 'If the day before yesterday was Thursday, what day will it be tomorrow?', 'If the day before yesterday was Thursday, then yesterday was Friday, and today is **Saturday**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00241', 'insurance-exam-bank', 'Reasoning Ability', 3, 25, 'In a certain code language, ''SUN'' is written as ''UWP''. How is ''MOON'' written in the same code?', 'Each letter is shifted **two steps forward** in the alphabet: S→U, U→W, N→P.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00242', 'insurance-exam-bank', 'Reasoning Ability', 3, 26, 'Find the missing number: 7, 14, 28, 56, ?', 'Each term is obtained by **doubling the previous term**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00243', 'insurance-exam-bank', 'Reasoning Ability', 3, 27, 'If ''TABLE'' is coded as ''UBCMF'', what is the coding rule, and how is ''CHAIR'' coded?', 'Each letter is shifted **one step forward** in the alphabet: T→U, A→B, B→C, L→M, E→F.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00244', 'insurance-exam-bank', 'Reasoning Ability', 3, 28, 'A is the son of B. B is the sister of C. C is the father of D. How is A related to C?', 'B is the sister of C, and A is the son of B, making A the **nephew** of C.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00245', 'insurance-exam-bank', 'Reasoning Ability', 3, 29, 'Which word does NOT belong with the others: Mumbai, Delhi, Kolkata, India?', 'Mumbai, Delhi, and Kolkata are all **cities**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00246', 'insurance-exam-bank', 'Reasoning Ability', 3, 30, 'If ''+'' means ''divided by'', ''−'' means ''multiplied by'', ''×'' means ''added to'', and ''÷'' means ''subtracted from'', evaluate: 8 × 4 ÷ 2 + 1.', 'Substituting the swapped meanings: ''×'' becomes ''+'', ''÷'' becomes ''−'', ''+'' becomes ''÷''.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00247', 'insurance-exam-bank', 'Reasoning Ability', 3, 31, 'In a queue, Ramesh is 15th from the front and 8th from the end. How many people are there in the queue?', 'Total people `= (position from front) + (position from end) − 1 = 15 + 8 − 1 = 22`.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00248', 'insurance-exam-bank', 'Reasoning Ability', 3, 32, 'A man walks 4 km north, then 3 km east. How far is he from his starting point?', 'Since north and east are perpendicular directions, the straight-line distance from the starting point is found using the Pythagorean theorem: `√(4² + 3²) = √(16+9) = √25 = 5`.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00249', 'insurance-exam-bank', 'Reasoning Ability', 3, 33, 'Look at the series: Z, X, V, T, ... What comes next?', 'Each letter is **two steps back** in the alphabet from the previous one: Z→X (skip Y), X→V (skip W), V→T (skip U).
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00250', 'insurance-exam-bank', 'Reasoning Ability', 3, 34, 'If all cats are dogs, and all dogs are animals, which of the following must be true: all cats are animals, or all animals are cats?', 'Since all cats are dogs, and all dogs are animals, it follows logically (by transitivity) that **all cats are animals**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00251', 'insurance-exam-bank', 'Reasoning Ability', 3, 35, 'Ravi''s mother is the only daughter of Suresh. How is Suresh related to Ravi?', 'Ravi''s mother is Suresh''s only daughter, which means Suresh is the father of Ravi''s mother.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00252', 'insurance-exam-bank', 'Reasoning Ability', 3, 36, 'Find the next number: 1, 1, 2, 3, 5, 8, ?', 'This is the **Fibonacci sequence**, where each term is the sum of the two preceding terms.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00253', 'insurance-exam-bank', 'Reasoning Ability', 3, 37, 'If the first and second letters in the word ''COMPUTER'' are interchanged, likewise the third and fourth, and so on, what will be the sixth letter of the new arrangement counted from the left?', 'Original word: C-O-M-P-U-T-E-R (positions 1-8).
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00254', 'insurance-exam-bank', 'Reasoning Ability', 3, 38, 'Pointing to a man, a woman said, "His mother is the only daughter of my mother." How is the woman related to the man?', 'The woman''s mother''s only daughter is the woman herself (since she is the only daughter).
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00255', 'insurance-exam-bank', 'Reasoning Ability', 3, 39, 'Which number should replace the question mark: 3, 6, 11, 18, 27, ?', 'The differences between consecutive terms are `3, 5, 7, 9`, increasing by 2 each time (consecutive odd numbers).
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00256', 'insurance-exam-bank', 'Reasoning Ability', 3, 40, 'In a group of 60 people, 25 can speak Hindi, 40 can speak English, and 10 can speak both. How many can speak neither language?', 'Using the formula for union of two sets: people who speak at least one language `= 25 + 40 − 10 = 55`.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00257', 'insurance-exam-bank', 'Reasoning Ability', 3, 41, 'Deepak ranks 7th from the top and 18th from the bottom in a class. How many students are there in the class?', 'Total students `= (rank from top) + (rank from bottom) − 1 = 7 + 18 − 1 = 24`.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00258', 'insurance-exam-bank', 'Reasoning Ability', 3, 42, 'If South becomes East, what will West become, under the same rotation rule?', 'South becoming East represents a **90° anticlockwise rotation** of directions.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00259', 'insurance-exam-bank', 'Reasoning Ability', 3, 43, 'Find the odd one out: 8, 27, 64, 100, 125.', '8 (2³), 27 (3³), 64 (4³), and 125 (5³) are all **perfect cubes**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00260', 'insurance-exam-bank', 'Reasoning Ability', 3, 44, 'Find the odd one out: 121, 144, 169, 200.', '121 (11²), 144 (12²), and 169 (13²) are all **perfect squares**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00261', 'insurance-exam-bank', 'Reasoning Ability', 3, 45, 'A is the son of C. C and Q are sisters. B is the mother of Q. How is A related to B?', 'C and Q are sisters, and B is the mother of Q, making B the mother of C as well.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00262', 'insurance-exam-bank', 'Reasoning Ability', 3, 46, 'If in a certain language, ''RIVER'' is coded as ''SJWFS'', what is the coding rule, and how is ''LAKE'' coded?', 'Each letter is shifted **one step forward** in the alphabet: R→S, I→J, V→W, E→F, R→S.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00263', 'insurance-exam-bank', 'Reasoning Ability', 3, 47, 'A clock shows 4:00. What is the angle between the hour and minute hands?', 'At 4:00, the minute hand is at 12, and the hour hand is at 4.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00264', 'insurance-exam-bank', 'Reasoning Ability', 3, 48, 'How many Sundays are there in a year that begins on a Sunday (non-leap year)?', 'A non-leap year has 365 days, which is `52 weeks and 1 extra day` (`365 = 52 × 7 + 1`).
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00265', 'insurance-exam-bank', 'Reasoning Ability', 3, 49, 'Six friends A, B, C, D, E, and F sit around a circular table facing the centre. A is between B and C. D is directly opposite A, and E is immediately to the right of D. Who is immediately to the left of D?', 'With 6 equally spaced seats, the person opposite A is 3 seats away, so fixing A, B, and C around one side leaves D opposite A, and E immediately to D''s right, as given.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00266', 'insurance-exam-bank', 'Reasoning Ability', 3, 50, 'If the word ''GARDEN'' is written in reverse order, which letter comes third from the left?', '''GARDEN'' reversed becomes **N-E-D-R-A-G**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00267', 'insurance-exam-bank', 'Reasoning Ability', 3, 51, 'Find the odd pair: (4,16), (5,25), (6,42), (7,49).', 'In (4,16), (5,25), and (7,49), the second number is the **square** of the first (4²=16, 5²=25, 7²=49).
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00268', 'insurance-exam-bank', 'Reasoning Ability', 3, 52, 'A says, "B''s father is the only son of my father." How is A related to B?', 'B''s father is the only son of A''s father, meaning B''s father and A are children of the same father, and since he is the ''only son'', B''s father is A **himself** or A''s brother.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00269', 'insurance-exam-bank', 'Reasoning Ability', 3, 53, 'Arrange in ascending order of size: Village, Country, District, State.', 'The ascending order, from smallest administrative unit to largest, is: **Village, District, State, Country**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00270', 'insurance-exam-bank', 'Reasoning Ability', 3, 54, 'If ''5 # 3'' means ''5 is the father of 3'' and ''3 @ 5'' means ''3 is the daughter of 5'', what does ''A # B @ C'' indicate about the relationship between A and C?', '''A # B'' means A is the father of B. ''B @ C'' means B is the daughter of C, i.e., C is the parent of B.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00271', 'insurance-exam-bank', 'Reasoning Ability', 3, 55, 'Find the next letter-group in the series: AZ, BY, CX, DW, ?', 'The first letter of each pair moves **forward** (A, B, C, D...) while the second letter moves **backward** (Z, Y, X, W...) through the alphabet.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00272', 'insurance-exam-bank', 'Reasoning Ability', 3, 56, 'How many triangles can be formed using 6 non-collinear points, no three of which are collinear, taking 3 points at a time?', 'This is a combination problem: choosing 3 points out of 6 to form a triangle `= C(6,3) = 6!/(3!×3!) = 20`.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00273', 'insurance-exam-bank', 'Reasoning Ability', 3, 57, 'If Monday is coded as 2, Tuesday as 4, Wednesday as 6, what is Friday coded as, following the same pattern?', 'The code follows the pattern of **(day''s position in the week) × 2**: Monday (1st day) = 2, Tuesday (2nd day) = 4, Wednesday (3rd day) = 6.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00274', 'insurance-exam-bank', 'Reasoning Ability', 3, 58, 'A man introduces a woman as, "She is the daughter of my wife''s mother-in-law''s only daughter-in-law." How is the woman related to the man?', 'The man''s wife''s mother-in-law is the man''s own mother. Her only daughter-in-law is the man''s wife herself.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00275', 'insurance-exam-bank', 'Reasoning Ability', 3, 59, 'Which of the following does not belong with the group: Rose, Lotus, Jasmine, Mango?', 'Rose, Lotus, and Jasmine are all **flowers**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00276', 'insurance-exam-bank', 'Reasoning Ability', 3, 60, 'If the 2nd of a month is a Tuesday, what day of the week is the 30th of the same month?', 'From the 2nd to the 30th is `30 − 2 = 28` days, and `28` is exactly divisible by 7.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00277', 'insurance-exam-bank', 'Reasoning Ability', 3, 61, 'A, B, C, D are standing in a line. B is to the immediate right of A. C is to the immediate right of B. D is to the immediate left of A. What is the order from left to right?', 'D is immediately to the left of A, so the order so far is: D, A.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00278', 'insurance-exam-bank', 'Reasoning Ability', 3, 62, 'Find the missing term: 2, 5, 10, 17, 26, ?', 'The differences between consecutive terms are `3, 5, 7, 9`, which are consecutive odd numbers.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00279', 'insurance-exam-bank', 'Reasoning Ability', 3, 63, 'In a mirror, the image of a clock shows 3:40. What is the actual time?', 'The mirror image time and the actual time add up to **11:60 (i.e., 12:00)** on a standard 12-hour clock face.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00280', 'insurance-exam-bank', 'Reasoning Ability', 3, 64, 'If ''A'' is coded as 1, ''B'' as 2, and so on, find the code for the word ''CAB''.', 'Using A=1, B=2, C=3: C=3, A=1, B=2.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00281', 'insurance-exam-bank', 'Reasoning Ability', 3, 65, 'Among five people P, Q, R, S, T, P is taller than Q but shorter than R. S is the tallest, and T is taller than Q but shorter than P. Who is the shortest?', 'From the clues: `S > R > P > T > Q`.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00282', 'insurance-exam-bank', 'Reasoning Ability', 3, 66, 'Find the odd one out: Delhi, Mumbai, Chennai, Himalayas.', 'Delhi, Mumbai, and Chennai are **cities**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00283', 'insurance-exam-bank', 'Reasoning Ability', 3, 67, 'A is twice as old as B was 5 years ago. If B''s present age is 20 years, find A''s present age.', 'B''s age 5 years ago `= 20 − 5 = 15`.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00284', 'insurance-exam-bank', 'Reasoning Ability', 3, 68, 'If ''LOTUS'' is written as ''MPUVT'', what is the rule, and what is ''ROSE'' written as?', 'Each letter is shifted **one step forward** in the alphabet: L→M, O→P, T→U, U→V, S→T.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00285', 'insurance-exam-bank', 'Reasoning Ability', 3, 69, 'Which number will complete the series: 4, 9, 16, 25, 36, ?', 'The series consists of perfect squares: `2², 3², 4², 5², 6²`.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00286', 'insurance-exam-bank', 'Reasoning Ability', 3, 70, 'A person walks 10 m north, turns right and walks 10 m, then turns right again and walks 10 m. In which direction is he now facing, and how far is he from the start?', 'Path: north 10 m, then right turn (east) 10 m, then right turn again (south) 10 m.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00287', 'insurance-exam-bank', 'English Language', 4, 0, 'Choose the correct sentence: (a) He don''t like tea. (b) He doesn''t like tea.', 'With a third-person singular subject (''He''), the auxiliary verb must be **''doesn''t''**, not ''don''t''.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00288', 'insurance-exam-bank', 'English Language', 4, 1, 'Identify the error, if any: ''Each of the students have submitted their assignment.''', 'The subject ''Each'' is singular and must take a **singular verb**, so ''have'' should be corrected to **''has''**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00289', 'insurance-exam-bank', 'English Language', 4, 2, 'Fill in the blank with the correct preposition: ''She is good ___ mathematics.''', 'The idiomatic preposition that follows the adjective ''good'' (in the sense of being skilled) is **''at''**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00290', 'insurance-exam-bank', 'English Language', 4, 3, 'Fill in the blank with the correct preposition: ''He is afraid ___ dogs.''', 'The adjective ''afraid'' is conventionally followed by the preposition **''of''**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00291', 'insurance-exam-bank', 'English Language', 4, 4, 'Choose the correct article: ''___ European Union has 27 member states.''', 'Although ''European'' starts with a vowel letter, it begins with a **consonant sound** (''yoo-ropean''), so the article **''The''** (not ''An'') is used, as is standard before proper nouns referring to a specific union.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00292', 'insurance-exam-bank', 'English Language', 4, 5, 'Convert into passive voice: ''The manager approved the proposal.''', 'In passive voice, the object of the active sentence (''the proposal'') becomes the subject, and the verb changes to ''be + past participle''.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00293', 'insurance-exam-bank', 'English Language', 4, 6, 'Convert into passive voice: ''They are building a new office.''', 'For a present continuous active sentence, the passive form uses ''is/are being + past participle''.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00294', 'insurance-exam-bank', 'English Language', 4, 7, 'Convert into active voice: ''The letter was written by Rina.''', 'In active voice, the doer of the action (''Rina'') becomes the subject.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00295', 'insurance-exam-bank', 'English Language', 4, 8, 'Change into indirect speech: She said, "I am going to the market."', 'In reported speech, the tense shifts back (present continuous → past continuous) and the pronoun changes accordingly.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00296', 'insurance-exam-bank', 'English Language', 4, 9, 'Change into indirect speech: He said, "I have finished my homework."', 'The present perfect tense (''have finished'') shifts back to the **past perfect tense** in indirect/reported speech.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00297', 'insurance-exam-bank', 'English Language', 4, 10, 'Give a synonym for the word ''Benevolent''.', '''Benevolent'' means kind, generous, and well-meaning towards others.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00298', 'insurance-exam-bank', 'English Language', 4, 11, 'Give a synonym for the word ''Candid''.', '''Candid'' means truthful and straightforward, especially about something that is awkward or difficult to discuss.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00299', 'insurance-exam-bank', 'English Language', 4, 12, 'Give an antonym for the word ''Abundant''.', '''Abundant'' means existing or available in large quantities; plentiful.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00300', 'insurance-exam-bank', 'English Language', 4, 13, 'Give an antonym for the word ''Ancient''.', '''Ancient'' means belonging to the very distant past; very old.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00301', 'insurance-exam-bank', 'English Language', 4, 14, 'Give an antonym for the word ''Optimistic''.', '''Optimistic'' means hopeful and confident about the future.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00302', 'insurance-exam-bank', 'English Language', 4, 15, 'What is the one-word substitute for ''a person who knows many languages''?', 'The correct one-word substitute is **''Polyglot''**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00303', 'insurance-exam-bank', 'English Language', 4, 16, 'What is the one-word substitute for ''a place where orphans live''?', 'The correct one-word substitute is **''Orphanage''**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00304', 'insurance-exam-bank', 'English Language', 4, 17, 'What is the one-word substitute for ''handwriting that cannot be read''?', 'The correct one-word substitute is **''Illegible''**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00305', 'insurance-exam-bank', 'English Language', 4, 18, 'What is the one-word substitute for ''a person who loves books''?', 'The correct one-word substitute is **''Bibliophile''**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00306', 'insurance-exam-bank', 'English Language', 4, 19, 'What is the meaning of the idiom ''to break the ice''?', 'The idiom ''to break the ice'' means **to initiate a conversation or ease the tension in a social situation**, especially among people meeting for the first time.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00307', 'insurance-exam-bank', 'English Language', 4, 20, 'What is the meaning of the idiom ''once in a blue moon''?', 'The idiom ''once in a blue moon'' means **something that happens very rarely**, almost never.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00308', 'insurance-exam-bank', 'English Language', 4, 21, 'What is the meaning of the idiom ''to spill the beans''?', 'The idiom ''to spill the beans'' means **to reveal a secret** or disclose confidential information, often unintentionally.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00309', 'insurance-exam-bank', 'English Language', 4, 22, 'What is the meaning of the idiom ''a piece of cake''?', 'The idiom ''a piece of cake'' means **something that is very easy to do**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00310', 'insurance-exam-bank', 'English Language', 4, 23, 'What is the meaning of the idiom ''to hit the nail on the head''?', 'The idiom ''to hit the nail on the head'' means **to describe exactly what is causing a situation or problem**; to be precisely correct about something.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00311', 'insurance-exam-bank', 'English Language', 4, 24, 'Identify the correctly spelt word: (a) Accomodate (b) Accommodate.', 'The word ''accommodate'' has a **double ''c'' and double ''m''**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00312', 'insurance-exam-bank', 'English Language', 4, 25, 'Identify the correctly spelt word: (a) Occurence (b) Occurrence.', 'The word ''occurrence'' has a **double ''c'' and double ''r''**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00313', 'insurance-exam-bank', 'English Language', 4, 26, 'Identify the error in the sentence: ''Neither of the two boys were present.''', '''Neither'' is a singular pronoun and requires a **singular verb**, so ''were'' should be corrected to **''was''**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00314', 'insurance-exam-bank', 'English Language', 4, 27, 'Identify the error in the sentence: ''She is one of the best singer in the city.''', 'After ''one of the'', the noun must be **plural**, since it refers to one among several, so ''singer'' should be **''singers''**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00315', 'insurance-exam-bank', 'English Language', 4, 28, 'Identify the error in the sentence: ''He has gone to Delhi since Monday.''', 'When referring to a point in time up to the present (''since Monday''), the correct tense is the **present perfect**, so ''has gone'' should be **''has been''**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00316', 'insurance-exam-bank', 'English Language', 4, 29, 'Choose the correctly punctuated sentence: (a) ''What a beautiful day!'' (b) ''What a beautiful day.''', 'An exclamatory sentence expressing strong emotion should end with an **exclamation mark**, not a full stop.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00317', 'insurance-exam-bank', 'English Language', 4, 30, 'Fill in the blank with the correct form of the verb: ''If I ___ rich, I would travel the world.''', 'This is a **second conditional** (hypothetical/unreal present), which requires the **subjunctive past tense ''were''** for all subjects, not ''was''.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00318', 'insurance-exam-bank', 'English Language', 4, 31, 'Fill in the blank with the correct form of the verb: ''By the time we reached the station, the train ___ already left.''', 'Since one past action (train leaving) occurred **before** another past action (reaching the station), the **past perfect tense** is required.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00319', 'insurance-exam-bank', 'English Language', 4, 32, 'Choose the correct form: ''She is ___ honest woman.''', 'The word ''honest'' begins with a **silent ''h''**, making its first sound a vowel sound, so it takes the article **''an''**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00320', 'insurance-exam-bank', 'English Language', 4, 33, 'What type of sentence is ''Please close the door''?', 'This sentence gives a request or command, making it an **imperative sentence**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00321', 'insurance-exam-bank', 'English Language', 4, 34, 'What type of sentence is ''What a wonderful view this is!''?', 'This sentence expresses strong emotion or feeling, making it an **exclamatory sentence**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00322', 'insurance-exam-bank', 'English Language', 4, 35, 'Rearrange the words to form a meaningful sentence: ''to / library / every / the / he / day / goes''.', 'The meaningful sentence is: **''He goes to the library every day.''**', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00323', 'insurance-exam-bank', 'English Language', 4, 36, 'Identify the correct plural form of ''Analysis''.', '''Analysis'' is a word of Greek origin following an irregular plural pattern (singular ''-is'' → plural ''-es'').
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00324', 'insurance-exam-bank', 'English Language', 4, 37, 'Identify the correct plural form of ''Criterion''.', '''Criterion'' is a word of Greek origin with an irregular plural.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00325', 'insurance-exam-bank', 'English Language', 4, 38, 'What is the past tense of the irregular verb ''Begin''?', 'The past tense of ''Begin'' is **''Began''** (and the past participle is ''Begun'').', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00326', 'insurance-exam-bank', 'English Language', 4, 39, 'What is the past participle of the irregular verb ''Swim''?', 'The past participle of ''Swim'' is **''Swum''** (past tense is ''Swam'').', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00327', 'insurance-exam-bank', 'English Language', 4, 40, 'Choose the correctly structured sentence: (a) ''I enjoy to read books.'' (b) ''I enjoy reading books.''', 'The verb ''enjoy'' is conventionally followed by a **gerund (verb + -ing)**, not an infinitive.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00328', 'insurance-exam-bank', 'English Language', 4, 41, 'What does the phrase ''to turn a blind eye'' mean?', 'The phrase ''to turn a blind eye'' means **to deliberately ignore or pretend not to notice** something wrong or undesirable.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00329', 'insurance-exam-bank', 'English Language', 4, 42, 'What does the phrase ''to be on cloud nine'' mean?', 'The phrase ''to be on cloud nine'' means **to feel extremely happy or elated**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00330', 'insurance-exam-bank', 'English Language', 4, 43, 'Choose the correct option: ''Each of the boys ___ given a prize.''', '''Each'' is a singular indefinite pronoun and requires a **singular verb** form.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00331', 'insurance-exam-bank', 'English Language', 4, 44, 'Choose the correct word: ''The number of unemployed people ___ increasing.''', 'When ''the number of'' is used as the subject, it is treated as **singular**, so the verb should be ''is'', not ''are''.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00332', 'insurance-exam-bank', 'English Language', 4, 45, 'Choose the correct word: ''A number of students ___ absent today.''', 'When ''a number of'' is used as the subject (meaning ''several''), it is treated as **plural**, so the verb should be ''are''.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00333', 'insurance-exam-bank', 'English Language', 4, 46, 'What is the meaning of the word ''Ubiquitous''?', '''Ubiquitous'' means **present, appearing, or found everywhere**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00334', 'insurance-exam-bank', 'English Language', 4, 47, 'What is the meaning of the word ''Meticulous''?', '''Meticulous'' means **showing great attention to detail; very careful and precise**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00335', 'insurance-exam-bank', 'English Language', 4, 48, 'What is the meaning of the word ''Ephemeral''?', '''Ephemeral'' means **lasting for a very short time; fleeting or transient**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00336', 'insurance-exam-bank', 'English Language', 4, 49, 'What is the meaning of the word ''Pragmatic''?', '''Pragmatic'' means **dealing with things sensibly and realistically, based on practical considerations rather than theory**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00337', 'insurance-exam-bank', 'English Language', 4, 50, 'What is the meaning of the word ''Austerity''?', '''Austerity'' means **extreme simplicity and a lack of luxuries or unnecessary expenditure**, often used in the context of strict economic measures.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00338', 'insurance-exam-bank', 'English Language', 4, 51, 'Give a synonym for the word ''Diligent''.', '''Diligent'' means showing persistent and careful effort in one''s work or duties.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00339', 'insurance-exam-bank', 'English Language', 4, 52, 'Give a synonym for the word ''Lucid''.', '''Lucid'' means expressed clearly; easy to understand.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00340', 'insurance-exam-bank', 'English Language', 4, 53, 'Give an antonym for the word ''Generous''.', '''Generous'' means showing a readiness to give more of something than is strictly necessary.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00341', 'insurance-exam-bank', 'English Language', 4, 54, 'Give an antonym for the word ''Transparent''.', '''Transparent'' means easy to see through, perceive, or detect; also, open and honest.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00342', 'insurance-exam-bank', 'English Language', 4, 55, 'Fill in the blank with the correct conjunction: ''He is poor ___ honest.''', 'The contrast between being poor and being honest (a positive quality despite poverty) is best expressed with the conjunction **''but''**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00343', 'insurance-exam-bank', 'English Language', 4, 56, 'Fill in the blank with the correct conjunction: ''Work hard ___ you will fail.''', 'To express a consequence of not doing the first action, the correct conjunction is **''or''** (meaning ''otherwise'').
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00344', 'insurance-exam-bank', 'English Language', 4, 57, 'Identify the correct question tag: ''She sings well, ___?''', 'Since the main clause is affirmative (''She sings''), the question tag must be **negative**, using the auxiliary ''does'' and the pronoun ''she''.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00345', 'insurance-exam-bank', 'English Language', 4, 58, 'Identify the correct question tag: ''They aren''t coming, ___?''', 'Since the main clause is negative (''aren''t''), the question tag must be **affirmative**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00346', 'insurance-exam-bank', 'English Language', 4, 59, 'Which word is closest in meaning to ''Scrutinize''?', '''Scrutinize'' means to examine something very closely and thoroughly.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00347', 'insurance-exam-bank', 'English Language', 4, 60, 'Which word is closest in meaning to ''Abolish''?', '''Abolish'' means to formally put an end to a system, practice, or institution.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00348', 'insurance-exam-bank', 'English Language', 4, 61, 'What is the one-word substitute for ''government by the rich''?', 'The correct one-word substitute is **''Plutocracy''**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00349', 'insurance-exam-bank', 'English Language', 4, 62, 'What is the one-word substitute for ''one who does not believe in the existence of God''?', 'The correct one-word substitute is **''Atheist''**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00350', 'insurance-exam-bank', 'English Language', 4, 63, 'What is the one-word substitute for ''a word that reads the same backward as forward''?', 'The correct one-word substitute is **''Palindrome''**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00351', 'insurance-exam-bank', 'English Language', 4, 64, 'What is the correct comparative form of the adjective ''Good''?', '''Good'' is an irregular adjective.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00352', 'insurance-exam-bank', 'English Language', 4, 65, 'What is the correct superlative form of the adjective ''Bad''?', '''Bad'' is an irregular adjective.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00353', 'insurance-exam-bank', 'English Language', 4, 66, 'Choose the correct sentence: (a) ''Neither the manager nor the employees was present.'' (b) ''Neither the manager nor the employees were present.''', 'When subjects are joined by ''neither...nor'', the verb agrees with the **subject closest to it** — here, ''employees'' (plural), so the verb must be ''were''.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00354', 'insurance-exam-bank', 'English Language', 4, 67, 'Choose the correct sentence: (a) ''Not only the teacher but also the students was happy.'' (b) ''Not only the teacher but also the students were happy.''', 'With ''not only...but also'', the verb agrees with the **nearer subject** — here, ''students'' (plural), so the verb must be ''were''.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00355', 'insurance-exam-bank', 'English Language', 4, 68, 'What is the meaning of the idiom ''to let the cat out of the bag''?', 'The idiom ''to let the cat out of the bag'' means **to accidentally reveal a secret**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00356', 'insurance-exam-bank', 'English Language', 4, 69, 'What is the meaning of the idiom ''to beat around the bush''?', 'The idiom ''to beat around the bush'' means **to avoid getting to the point of an issue, often to delay discussing something unpleasant or difficult**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00357', 'insurance-exam-bank', 'English Language', 4, 70, 'What is the meaning of the idiom ''to add fuel to the fire''?', 'The idiom ''to add fuel to the fire'' means **to make a bad situation worse**, often by saying or doing something that increases anger or tension.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00358', 'insurance-exam-bank', 'Current Affairs (Insurance & Finance)', 5, 0, 'What major GST change was made to individual life and health insurance premiums in 2025?', 'Following the GST Council''s 56th meeting (September 2025), individual **life insurance premiums (term, ULIP, endowment) and individual health insurance premiums** (including family floater and senior citizen policies), along with their reinsurance, were **exempted from GST**, effective **22 September 2025**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00359', 'insurance-exam-bank', 'Current Affairs (Insurance & Finance)', 5, 1, 'What is the key objective behind exempting individual insurance premiums from GST?', 'The objective is to make **insurance more affordable** for individual buyers, boost insurance penetration in India, and support the IRDAI''s broader **''Insurance for All by 2047''** mission, even though insurers lose input tax credit on exempted supplies.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00360', 'insurance-exam-bank', 'Current Affairs (Insurance & Finance)', 5, 2, 'What major reform did the ''Insurance Laws (Amendment) Bill, 2025'' bring regarding foreign investment?', 'The Bill, passed by Parliament in December 2025, raised the **Foreign Direct Investment (FDI) limit in the Indian insurance sector from 74% to 100%**, aiming to attract greater foreign capital and expertise into the sector.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00361', 'insurance-exam-bank', 'Current Affairs (Insurance & Finance)', 5, 3, 'Did the Insurance Laws (Amendment) Bill, 2025 introduce a ''composite license'' for insurers?', 'No — while an earlier draft had proposed a **composite license** (allowing a single insurer to sell life, general, and health insurance under one licence), this provision was **dropped from the final enacted bill**, though the law''s redefinition of ''class of insurance business'' is seen as laying statutory groundwork for it in the future.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00362', 'insurance-exam-bank', 'Current Affairs (Insurance & Finance)', 5, 4, 'What change did the Insurance Laws (Amendment) Bill, 2025 make to the threshold for IRDAI approval of share transfers in insurers?', 'The Bill raised the threshold requiring **prior IRDAI approval for share transfers/issuances in an insurance company from 1% to 5%** of the paid-up capital, easing the compliance burden for minor shareholding changes.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00363', 'insurance-exam-bank', 'Current Affairs (Insurance & Finance)', 5, 5, 'What are the three components of IRDAI''s ''Bima Trinity'' reform package aimed at expanding insurance access?', 'The Bima Trinity comprises **Bima Sugam** (a unified digital insurance marketplace), **Bima Vistaar** (a simple, affordable bundled insurance product for the underserved), and **Bima Vahak** (a women-led grassroots distribution network), together supporting IRDAI''s ''Insurance for All by 2047'' vision.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00364', 'insurance-exam-bank', 'Current Affairs (Insurance & Finance)', 5, 6, 'What is the IRDAI''s Risk Based Capital (RBC) framework intended to replace?', 'The RBC framework is intended to replace India''s current **factor-based (rule-based) solvency margin regime**, with a more sophisticated approach that aligns capital requirements with an insurer''s **actual underlying risk profile**, in line with international practices; it is being rolled out through Quantitative Impact Studies before formal notification.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00365', 'insurance-exam-bank', 'Current Affairs (Insurance & Finance)', 5, 7, 'What accounting standard transition is the Indian insurance industry undergoing alongside the RBC framework?', 'Indian insurers are transitioning to **Ind AS (Indian Accounting Standards)**-based financial reporting, moving away from the earlier regulatory reporting framework, with IRDAI providing a transition/parallel-reporting period to ease implementation.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00366', 'insurance-exam-bank', 'Current Affairs (Insurance & Finance)', 5, 8, 'What is the ''Unified Pension Scheme'' (UPS) introduced for central government employees?', 'UPS is a pension option notified by the Finance Ministry, effective **1 April 2025**, as an alternative to the National Pension System (NPS) for central government employees, offering an **assured payout of 50% of the average basic pay** of the last 12 months before retirement for employees with 25+ years of qualifying service.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00367', 'insurance-exam-bank', 'Current Affairs (Insurance & Finance)', 5, 9, 'How is the Unified Pension Scheme (UPS) funded, in terms of employee contribution?', 'Under UPS, employees contribute **10% of their basic pay plus dearness allowance (DA)**, similar to the NPS contribution structure, with the government providing a matching and additional contribution to fund the assured payout guarantee.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00368', 'insurance-exam-bank', 'Current Affairs (Insurance & Finance)', 5, 10, 'Who is the current Governor of the Reserve Bank of India, and since when?', '**Sanjay Malhotra**, a 1990-batch IAS officer and former Union Revenue Secretary, has served as RBI Governor since **11 December 2024**, succeeding Shaktikanta Das.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00369', 'insurance-exam-bank', 'Current Affairs (Insurance & Finance)', 5, 11, 'What is the top-up health cover introduced for senior citizens under Ayushman Bharat PM-JAY?', 'Since September 2024, all senior citizens aged **70 years and above** are eligible for an **additional ₹5 lakh per year health cover**, provided exclusively for their own use, over and above any family cover they may already have under PM-JAY.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00370', 'insurance-exam-bank', 'Current Affairs (Insurance & Finance)', 5, 12, 'What is the purpose of IRDAI''s ''Insurance for All by 2047'' mission?', 'It is IRDAI''s stated goal that **every citizen has adequate life, health, and property insurance**, and every enterprise is appropriately covered, by the time India completes **100 years of independence (2047)**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00371', 'insurance-exam-bank', 'Current Affairs (Insurance & Finance)', 5, 13, 'What recent proposal has been discussed regarding the sum assured under PMJJBY?', 'The government has been examining a proposal to **raise the life cover under PMJJBY from ₹2 lakh to ₹4 lakh**, along with a corresponding revision in the annual premium, in response to representations about inadequate coverage given rising costs.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00372', 'insurance-exam-bank', 'Current Affairs (Insurance & Finance)', 5, 14, 'What is the current annual premium and cover amount under the Pradhan Mantri Suraksha Bima Yojana (PMSBY)?', 'PMSBY currently offers an accidental death/total disability cover of **₹2 lakh** for an annual premium of **₹20**, after the premium was revised upward from ₹12 in 2022 due to adverse claims experience.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00373', 'insurance-exam-bank', 'Current Affairs (Insurance & Finance)', 5, 15, 'What is the significance of the IRDAI (Insurance Products) Regulations, 2024 in simplifying product regulation?', 'These regulations consolidated and replaced multiple earlier product-related regulations for life, health, and general insurance into a **single, principle-based framework**, giving insurers greater flexibility to design and price products while strengthening policyholder protection norms.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00374', 'insurance-exam-bank', 'Current Affairs (Insurance & Finance)', 5, 16, 'What is the broader significance of raising FDI in insurance to 100%?', 'Allowing 100% FDI permits **global insurers to wholly own their Indian subsidiaries** without needing a domestic joint-venture partner, expected to bring in greater capital, technical expertise, and deeper insurance penetration, while existing promoters can still choose to retain Indian partners.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00375', 'insurance-exam-bank', 'Current Affairs (Insurance & Finance)', 5, 17, 'What is the main criticism of dropping the ''composite licence'' proposal from the Insurance Amendment Bill, 2025?', 'Critics argue that without composite licensing, insurers wishing to offer life, general, and health products together must still **maintain separate licensed entities** for each class of business, limiting the operational and capital efficiencies that a unified licence would have enabled.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00376', 'insurance-exam-bank', 'Current Affairs (Insurance & Finance)', 5, 18, 'What does the term ''Bima Sugam'' aim to solve for insurance customers?', 'Bima Sugam aims to let customers **compare, buy, and manage policies from multiple insurers on one digital platform**, while also enabling faster claims processing and policy portability, reducing information asymmetry and mis-selling in insurance distribution.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00377', 'insurance-exam-bank', 'Current Affairs (Insurance & Finance)', 5, 19, 'What is the IRDAI''s stance on commission caps for insurance intermediaries, under the amended Insurance laws?', 'The amended law empowers **IRDAI to prescribe caps on commissions** payable to insurance agents and intermediaries, aimed at curbing excessive commission-driven mis-selling while ensuring adequate incentives for genuine distribution.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00378', 'insurance-exam-bank', 'Current Affairs (Insurance & Finance)', 5, 20, 'What recent step has IRDAI taken concerning micro-insurance and rural insurance penetration?', 'IRDAI has pushed the **Bima Vistaar** composite product (bundling life, health, personal accident, and property cover) and the **Bima Vahak** women-led distribution channel to improve insurance penetration in rural and underserved regions, as part of its 2047 roadmap.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00379', 'insurance-exam-bank', 'Current Affairs (Insurance & Finance)', 5, 21, 'What was the key finding behind the GST Council''s decision to exempt health insurance premiums?', 'The decision followed recognition that **GST on health insurance added to the cost of healthcare coverage** for ordinary citizens, discouraging the uptake of health insurance, especially among middle-income households, despite rising medical inflation.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00380', 'insurance-exam-bank', 'Current Affairs (Insurance & Finance)', 5, 22, 'What is a ''Quantitative Impact Study'' (QIS) in the context of IRDAI''s Risk Based Capital rollout?', 'A QIS is an exercise where insurers are asked to **compute their solvency position under the proposed new (risk-based) rules alongside the existing rules**, using real balance-sheet data, so that the regulator can assess the framework''s impact before finalising the rules.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00381', 'insurance-exam-bank', 'Current Affairs (Insurance & Finance)', 5, 23, 'What recent trend has been seen in the Indian health insurance segment regarding standalone health insurers?', 'Standalone Health Insurers (SAHIs) have been **gaining market share** relative to composite insurers in the retail health segment, driven by focused product innovation, rising hospitalisation costs, and wider health awareness post-pandemic.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00382', 'insurance-exam-bank', 'Current Affairs (Insurance & Finance)', 5, 24, 'Why is the move towards Ind AS considered significant for Indian insurers?', 'Ind AS reporting provides a more **transparent, market-consistent view of an insurer''s assets, liabilities, and profitability**, improving comparability with global peers and supporting better-informed decisions by investors, policyholders, and the regulator.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00383', 'insurance-exam-bank', 'Current Affairs (Insurance & Finance)', 5, 25, 'What is the significance of the Insurance Ombudsman mechanism being strengthened in recent years?', 'A strengthened Ombudsman mechanism, with digitised complaint processes and clearer timelines, improves the **speed and accessibility of grievance redressal** for policyholders, reducing the need to approach consumer courts for disputes.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00384', 'insurance-exam-bank', 'Current Affairs (Insurance & Finance)', 5, 26, 'What recent debate surrounds the raising of sum assured under PMJJBY and PMSBY?', 'Public sector banks and insurers have urged the Finance Ministry to **raise the sum assured under both PMJJBY and PMSBY**, arguing that the current cover amounts (₹2 lakh each) have not kept pace with inflation and rising cost of living since their 2015 launch.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00385', 'insurance-exam-bank', 'Current Affairs (Insurance & Finance)', 5, 27, 'What is the broader policy context behind India''s push for ''Insurance for All by 2047''?', 'The push reflects a recognition that India''s **insurance penetration (premium as a % of GDP) remains well below the global average**, and that expanding coverage is essential both for individual financial protection and for channeling long-term savings into the economy.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00386', 'insurance-exam-bank', 'Current Affairs (Insurance & Finance)', 5, 28, 'What is the significance of allowing 100% FDI together with retaining Indian management control requirements?', 'Even with 100% foreign ownership permitted, IRDAI has signalled it will continue to require that insurers operating in India have **a majority of resident Indian directors and a local-facing management structure**, balancing foreign capital inflows with regulatory oversight and accountability.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00387', 'insurance-exam-bank', 'Current Affairs (Insurance & Finance)', 5, 29, 'What is the key rationale for IRDAI consolidating multiple product regulations in 2024?', 'The consolidation was meant to **reduce regulatory complexity and time-to-market for new insurance products**, moving from a rules-heavy, file-and-use-approval-based regime towards more principle-based, insurer-accountable product governance.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00388', 'insurance-exam-bank', 'Current Affairs (Insurance & Finance)', 5, 30, 'What recent change has occurred in the regulation of co-operative banks that is relevant to the financial sector''s current affairs?', 'Following the Banking Regulation (Amendment) Act, 2020, the **RBI''s regulatory and supervisory powers were extended over co-operative banks**, a trend reinforced by subsequent RBI circulars aimed at strengthening governance and risk management in the co-operative banking sector.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00389', 'insurance-exam-bank', 'Current Affairs (Insurance & Finance)', 5, 31, 'What is the general direction of IRDAI''s regulatory philosophy signalled through its recent reforms (2024-2025)?', 'IRDAI''s recent reforms signal a shift from **strict, prescriptive rule-based regulation towards principle-based, ''ease of doing business'' regulation**, encouraging product innovation and insurer responsibility while strengthening policyholder protection and solvency oversight.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00390', 'insurance-exam-bank', 'Current Affairs (Insurance & Finance)', 5, 32, 'What is the long-term goal associated with India''s 100% FDI reform in insurance, in terms of market structure?', 'The reform is expected to encourage **more global insurers to enter or deepen their presence in the Indian market**, potentially intensifying competition, improving product innovation, and accelerating the technology adoption that supports digital distribution platforms like Bima Sugam.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00391', 'insurance-exam-bank', 'Current Affairs (Insurance & Finance)', 5, 33, 'How does the GST exemption on individual insurance premiums affect insurers'' costs, even though it benefits policyholders?', 'Since the exemption makes insurance premiums an **exempt supply** rather than a zero-rated one, insurers **lose the ability to claim input tax credit (ITC)** on GST paid for their own inputs and services, which can raise their effective operating costs even as customer premiums fall.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00392', 'insurance-exam-bank', 'Current Affairs (Insurance & Finance)', 5, 34, 'What is the broader macro rationale for the Unified Pension Scheme (UPS) being offered as an option rather than mandatory replacement of NPS?', 'Offering UPS as an **option alongside NPS** allows employees to choose between a market-linked pension (NPS) and an assured-benefit pension (UPS) based on their own risk appetite, while containing the government''s long-term fiscal liability compared to reverting fully to the old defined-benefit pension system.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00393', 'insurance-exam-bank', 'Current Affairs (Insurance & Finance)', 5, 35, 'What is the relevance of the Insurance Information Bureau''s expanding data-sharing role in recent reforms?', 'As IRDAI pushes digital platforms like Bima Sugam, the **IIB''s centralised policy and claims database** becomes increasingly important for detecting fraud, enabling data-driven underwriting, and supporting a unified customer policy history across insurers.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00394', 'insurance-exam-bank', 'Current Affairs (Insurance & Finance)', 5, 36, 'What recent concern has been raised by insurers regarding the delayed implementation of IRDAI''s Risk Based Capital framework?', 'Insurers have flagged concerns that **repeated delays in finalising the RBC framework** (with proposals ranging from April 2026 to a phased rollout through 2027) create planning uncertainty for capital raising and long-term business strategy.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00395', 'insurance-exam-bank', 'Current Affairs (Insurance & Finance)', 5, 37, 'What is the policy significance of extending GST exemption to the reinsurance of individual life and health policies?', 'Extending the exemption to **reinsurance of these policies** ensures that the tax benefit is not diluted or reversed further up the risk-transfer chain, keeping the overall cost of providing individual life/health cover lower for the end insurer and, in turn, the policyholder.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00396', 'insurance-exam-bank', 'Current Affairs (Insurance & Finance)', 5, 38, 'What broader financial inclusion trend connects PMJJBY, PMSBY, APY, and PM-JAY?', 'All four schemes represent India''s push towards **universal, affordable social security** — covering life risk (PMJJBY), accident risk (PMSBY), old-age income (APY), and health expenses (PM-JAY) — built on the foundation of Jan Dhan bank accounts and Aadhaar-linked delivery.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00397', 'insurance-exam-bank', 'Current Affairs (Insurance & Finance)', 5, 39, 'What is the key significance of IRDAI''s push for ''use and file'' instead of ''file and use'' for insurance products?', 'Under ''use and file'', insurers can **launch certain standard products immediately** and notify/file details with IRDAI afterward, rather than waiting for prior regulatory approval, significantly **speeding up time-to-market** for new insurance products.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00398', 'insurance-exam-bank', 'Current Affairs (Insurance & Finance)', 5, 40, 'Who was appointed as IRDAI Chairman in 2025, and what was his earlier government role?', '**Ajay Seth**, a former Union Finance Secretary, was appointed as IRDAI Chairman, taking charge in **September 2025**, succeeding Debasish Panda whose term had ended earlier that year.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00399', 'insurance-exam-bank', 'Current Affairs (Insurance & Finance)', 5, 41, 'What is the ''NPS Vatsalya'' scheme, launched in 2024?', 'NPS Vatsalya is a **pension scheme for minors**, launched on **18 September 2024**, allowing parents/guardians to open and contribute to an NPS account in a minor''s name, which converts into a regular NPS account once the child turns 18.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00400', 'insurance-exam-bank', 'Current Affairs (Insurance & Finance)', 5, 42, 'What is an ''IFSC Insurance Office'' (IIO) in GIFT City, Gujarat?', 'An IIO is an insurance or reinsurance business entity that Indian and foreign insurers can set up at India''s **International Financial Services Centre (IFSC) in GIFT City**, regulated by the **IFSCA**, to conduct cross-border insurance/reinsurance business under a liberalised regulatory regime.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00401', 'insurance-exam-bank', 'Current Affairs (Insurance & Finance)', 5, 43, 'What is the role of the IFSCA (International Financial Services Centres Authority) with respect to GIFT City?', 'IFSCA is the **unified regulator** for all financial services (banking, insurance, capital markets, and fund management) within International Financial Services Centres like GIFT City, consolidating powers that would otherwise fall separately under RBI, SEBI, IRDAI, and PFRDA.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00402', 'insurance-exam-bank', 'Current Affairs (Insurance & Finance)', 5, 44, 'What is the broader strategic goal behind setting up reinsurance branches (IIOs) in GIFT City?', 'The goal is to position India, through GIFT City, as a **global reinsurance and insurance services hub**, retaining reinsurance premium within the country (which otherwise flows to hubs like Singapore, Bermuda, or London) and deepening the domestic reinsurance capacity available to Indian insurers.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00403', 'insurance-exam-bank', 'Current Affairs (Insurance & Finance)', 5, 45, 'What is the 8th Central Pay Commission, and when were its Terms of Reference notified?', 'The 8th Central Pay Commission, set up to review pay, pensions, and allowances of central government employees, had its Terms of Reference notified by the Finance Ministry on **3 November 2025**, under the chairpersonship of **Justice Ranjana Prakash Desai**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00404', 'insurance-exam-bank', 'Current Affairs (Insurance & Finance)', 5, 46, 'How does the setting up of Pay Commissions relate to insurance and pension awareness for banking/insurance exam current affairs?', 'Pay Commission recommendations affect government employees'' **salary structure, pension entitlements (including NPS/UPS contributions), and gratuity**, making them directly relevant to the broader financial and social-security policy landscape tracked in these exams.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00405', 'insurance-exam-bank', 'Current Affairs (Insurance & Finance)', 5, 47, 'What recent trend is seen in India''s overall insurance penetration and density figures?', 'Despite reforms, India''s **insurance penetration (premium as % of GDP)** has remained below the global average, which is precisely the gap that initiatives like GST exemption, Bima Sugam, Bima Vistaar, and 100% FDI are designed to help close.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00406', 'insurance-exam-bank', 'Current Affairs (Insurance & Finance)', 5, 48, 'What is ''cyber insurance'' and why has its relevance grown in recent years?', 'Cyber insurance covers losses arising from **cyberattacks, data breaches, and related liabilities**; its relevance has grown sharply with increasing digitisation of businesses and individuals, and rising instances of ransomware and data-theft incidents in India.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00407', 'insurance-exam-bank', 'Current Affairs (Insurance & Finance)', 5, 49, 'What is ''parametric insurance'', increasingly discussed in the Indian agriculture/climate insurance context?', 'Parametric insurance pays out a **pre-agreed amount automatically when a specific measurable trigger occurs** (e.g., rainfall below a threshold, or an earthquake above a certain magnitude), rather than requiring a traditional loss assessment, enabling faster payouts for climate and disaster risks.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00408', 'insurance-exam-bank', 'Current Affairs (Insurance & Finance)', 5, 50, 'What is the ''Pradhan Mantri Fasal Bima Yojana'' (PMFBY)?', 'PMFBY is the government''s **crop insurance scheme**, launched in 2016, providing financial support to farmers in the event of crop failure due to natural calamities, pests, or diseases, with heavily subsidised premiums for farmers.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00409', 'insurance-exam-bank', 'Current Affairs (Insurance & Finance)', 5, 51, 'What recent reform trend applies to PMFBY regarding insurer participation?', 'IRDAI and the government have encouraged **more private general insurers to participate** in PMFBY tenders across states, aiming to improve claim settlement efficiency and reduce the financial burden historically concentrated on a few public insurers.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00410', 'insurance-exam-bank', 'Current Affairs (Insurance & Finance)', 5, 52, 'What is the significance of India''s push towards a ''Digital Rupee'' (Central Bank Digital Currency, CBDC) for the financial sector?', 'The RBI''s CBDC (e₹) pilot represents a **sovereign digital currency** issued directly by the central bank, aimed at complementing physical cash and existing digital payment systems like UPI, with implications for the future of digital settlement infrastructure relevant to insurance premium payments too.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00411', 'insurance-exam-bank', 'Current Affairs (Insurance & Finance)', 5, 53, 'What is ''embedded insurance'', a growing trend in India''s digital insurance distribution?', 'Embedded insurance refers to insurance cover **bundled directly into the purchase of another product or service** (e.g., travel insurance with a flight ticket, device protection with an electronics purchase), sold seamlessly at the point of sale, often enabled by API integrations between insurers and platforms.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00412', 'insurance-exam-bank', 'Current Affairs (Insurance & Finance)', 5, 54, 'What is the relevance of ''InsurTech'' in the context of India''s recent insurance sector evolution?', 'InsurTech refers to the use of **technology (AI, data analytics, mobile platforms) to innovate insurance distribution, underwriting, and claims processing**; it underpins platforms like Bima Sugam and is central to IRDAI''s broader digital-first regulatory push.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00413', 'insurance-exam-bank', 'Current Affairs (Insurance & Finance)', 5, 55, 'What is the key purpose of IRDAI''s ''Sandbox'' Regulations for insurance innovation?', 'The Regulatory Sandbox allows insurers and InsurTech firms to **test innovative products, technologies, or distribution models in a controlled environment** with regulatory relaxations, before a full-scale, compliant launch, encouraging responsible innovation in the sector.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00414', 'insurance-exam-bank', 'Current Affairs (Insurance & Finance)', 5, 56, 'What is the purpose of the ''Har Ghar Tiranga''-style financial literacy campaigns run alongside insurance awareness weeks?', 'IRDAI and the government periodically run **''Bima Jagrukta/Bima Literacy'' campaigns** to improve public understanding of insurance products, rights, and grievance redressal mechanisms, aiming to reduce mis-selling and improve informed decision-making by customers.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00415', 'insurance-exam-bank', 'Current Affairs (Insurance & Finance)', 5, 57, 'What is the relevance of India''s G20 presidency (2023) legacy to the financial/insurance sector reform narrative?', 'India''s G20 presidency placed emphasis on **financial inclusion, digital public infrastructure, and disaster risk insurance financing**, themes that continue to inform India''s domestic insurance and financial-sector reform agenda in subsequent years.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00416', 'insurance-exam-bank', 'Current Affairs (Insurance & Finance)', 5, 58, 'What does the term ''Digital Public Infrastructure'' (DPI) mean in the context of Bima Sugam?', 'DPI refers to **foundational, interoperable digital systems** (like Aadhaar, UPI, and now Bima Sugam) built as shared public utilities that multiple private and public players can build services on top of, rather than isolated proprietary systems.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00417', 'insurance-exam-bank', 'Current Affairs (Insurance & Finance)', 5, 59, 'What is the key purpose of India''s push for a ''National Health Claims Exchange'' (NHCX)?', 'NHCX is a digital platform, developed under the National Health Authority, intended to enable **seamless, standardised, and faster exchange of health insurance claims data** between hospitals, insurers, and TPAs, reducing claim settlement time and paperwork.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00418', 'insurance-exam-bank', 'Current Affairs (Insurance & Finance)', 5, 60, 'What is the significance of insurers increasingly offering ''wellness'' and ''preventive care'' benefits within health policies?', 'These benefits (e.g., free health check-ups, discounts for fitness tracking) reflect a shift from purely **reactive (treatment-based) to proactive (prevention-based) health insurance models**, incentivised by IRDAI''s product regulations encouraging wellness features.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00419', 'insurance-exam-bank', 'Current Affairs (Insurance & Finance)', 5, 61, 'What is the broader relevance of climate change to the general insurance industry''s current challenges?', 'Rising frequency of **floods, cyclones, and heatwaves** is increasing claims under property, crop, and catastrophe covers, pushing insurers and regulators to explore parametric products, better risk modelling, and catastrophe risk pooling mechanisms.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00420', 'insurance-exam-bank', 'Current Affairs (Insurance & Finance)', 5, 62, 'What is a ''catastrophe (cat) bond'', occasionally discussed in the context of disaster risk financing in India?', 'A catastrophe bond is a **risk-linked security** that transfers a specified catastrophic risk (like an earthquake or cyclone) from an insurer/government to capital market investors, who receive attractive yields but risk losing principal if the specified disaster event occurs.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00421', 'insurance-exam-bank', 'Current Affairs (Insurance & Finance)', 5, 63, 'What recent step highlights India''s deepening role in global reinsurance beyond GIC Re?', 'The growing number of **foreign reinsurers setting up IFSC Insurance Offices (IIOs) in GIFT City** (such as Allianz, Munich Re, Swiss Re affiliates, and others) reflects India''s deepening integration into the global reinsurance market, supplementing GIC Re''s domestic role.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00422', 'insurance-exam-bank', 'Current Affairs (Insurance & Finance)', 5, 64, 'What is the relevance of the ''Jan Suraksha'' schemes completing a decade in recent years?', 'PMJJBY, PMSBY, and APY completed **10 years since their 2015 launch** in 2025, prompting reviews of their coverage adequacy, enrolment numbers, and proposals to revise premium/sum-assured levels to reflect a decade of inflation.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00423', 'insurance-exam-bank', 'Current Affairs (Insurance & Finance)', 5, 65, 'What is the key policy debate around increasing the minimum capital requirement for standalone insurers in recent reform discussions?', 'Discussions around allowing **lower minimum capital requirements for niche/micro-insurers** (as opposed to the uniform ₹100 crore norm) aim to encourage smaller, specialised players to enter underserved insurance segments without diluting overall policyholder protection.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00424', 'insurance-exam-bank', 'Current Affairs (Insurance & Finance)', 5, 66, 'What is the relevance of the Reserve Bank''s continued focus on ''financial stability reports'' to the insurance sector?', 'RBI''s Financial Stability Reports periodically assess risks across the financial system, including the **interconnectedness between banks, NBFCs, and insurers**, helping regulators coordinate on systemic risk — relevant since insurers are major institutional investors in government securities and corporate bonds.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00425', 'insurance-exam-bank', 'Current Affairs (Insurance & Finance)', 5, 67, 'What is the significance of increasing bancassurance tie-ups being permitted with multiple insurers (open architecture)?', 'Under IRDAI''s ''open architecture'' norms, banks can tie up with **more than one life, general, and health insurer** (instead of being restricted to one each), giving customers greater product choice through the bancassurance channel.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00426', 'insurance-exam-bank', 'Current Affairs (Insurance & Finance)', 5, 68, 'What is the relevance of India''s ''Digital Personal Data Protection Act, 2023'' to the insurance sector''s current compliance landscape?', 'The Act imposes obligations on insurers (as significant handlers of sensitive personal and health data) regarding **consent-based data collection, purpose limitation, and data breach reporting**, requiring insurers to strengthen their data governance and cybersecurity frameworks.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00427', 'insurance-exam-bank', 'Current Affairs (Insurance & Finance)', 5, 69, 'What is the significance of the increasing adoption of video-based KYC (V-CIP) by insurers and banks?', 'Video-based Customer Identification Process allows **remote, paperless onboarding of customers** using live video verification, significantly speeding up policy issuance and account opening while reducing the need for physical branch visits.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00428', 'insurance-exam-bank', 'Current Affairs (Insurance & Finance)', 5, 70, 'What is the current broad direction of India''s insurance regulatory reforms, taken together (FDI, GST exemption, Bima Trinity, RBC, Ind AS)?', 'Taken together, these reforms point to a strategy of **simultaneously lowering costs for policyholders, attracting global capital and expertise, modernising digital distribution, and strengthening prudential (risk-based) oversight**, all aimed at closing India''s insurance protection gap by 2047.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00429', 'insurance-exam-bank', 'Computer Awareness', 6, 0, 'What is the full form of CPU, and what is its function?', 'CPU stands for **Central Processing Unit**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00430', 'insurance-exam-bank', 'Computer Awareness', 6, 1, 'What are the main components of a CPU?', 'The CPU consists of three main components:
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00431', 'insurance-exam-bank', 'Computer Awareness', 6, 2, 'What is the difference between RAM and ROM?', '**RAM (Random Access Memory)** is **volatile** memory — it loses its data when power is switched off, and is used for temporary storage of currently running programs and data.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00432', 'insurance-exam-bank', 'Computer Awareness', 6, 3, 'What is ''cache memory'' in a computer system?', 'Cache memory is a **small, high-speed memory located close to (or inside) the CPU** that stores frequently accessed data and instructions, reducing the time the CPU needs to access data from the comparatively slower main memory (RAM).', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00433', 'insurance-exam-bank', 'Computer Awareness', 6, 4, 'What is the difference between ''primary memory'' and ''secondary memory''?', '**Primary memory** (RAM, cache) is **volatile, faster, and directly accessible by the CPU**, used for temporary data during processing.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00434', 'insurance-exam-bank', 'Computer Awareness', 6, 5, 'What is the difference between ''input devices'' and ''output devices''? Give one example of each.', '**Input devices** are used to **feed data/instructions into a computer** (e.g., keyboard, mouse, scanner).
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00435', 'insurance-exam-bank', 'Computer Awareness', 6, 6, 'What is an ''Operating System'' (OS)?', 'An Operating System is **system software** that manages computer hardware and software resources, providing common services for application programs — examples include Windows, Linux, macOS, and Android.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00436', 'insurance-exam-bank', 'Computer Awareness', 6, 7, 'What is the difference between ''system software'' and ''application software''?', '**System software** manages and controls computer hardware so that application software can perform its intended tasks (e.g., operating systems, device drivers).
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00437', 'insurance-exam-bank', 'Computer Awareness', 6, 8, 'What does ''booting'' mean in computer terminology?', 'Booting refers to the process of **starting up a computer** and loading the operating system into memory, so the system becomes ready for use.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00438', 'insurance-exam-bank', 'Computer Awareness', 6, 9, 'What is a ''compiler'' in computer programming?', 'A compiler is a program that **translates source code written in a high-level programming language into machine code (object code)** all at once, before the program is executed, unlike an interpreter which translates and executes line by line.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00439', 'insurance-exam-bank', 'Computer Awareness', 6, 10, 'What is the difference between a ''compiler'' and an ''interpreter''?', 'A **compiler** translates the entire source code into machine code at once, producing an executable file, before execution begins.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00440', 'insurance-exam-bank', 'Computer Awareness', 6, 11, 'What is an ''IP address''?', 'An IP (Internet Protocol) address is a **unique numerical label assigned to every device connected to a computer network** that uses the Internet Protocol for communication, used to identify and locate the device on the network.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00441', 'insurance-exam-bank', 'Computer Awareness', 6, 12, 'What is the difference between IPv4 and IPv6?', '**IPv4** uses a **32-bit address** format (e.g., 192.168.1.1), offering around 4.3 billion unique addresses.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00442', 'insurance-exam-bank', 'Computer Awareness', 6, 13, 'What is the full form of ''HTTP'' and ''HTTPS''?', 'HTTP stands for **HyperText Transfer Protocol**, the foundational protocol used to transfer data over the web.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00443', 'insurance-exam-bank', 'Computer Awareness', 6, 14, 'What is a ''firewall'' in computer security?', 'A firewall is a **network security system (hardware or software)** that monitors and controls incoming and outgoing network traffic based on predetermined security rules, acting as a barrier between a trusted internal network and untrusted external networks.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00444', 'insurance-exam-bank', 'Computer Awareness', 6, 15, 'What is the difference between a ''virus'' and a ''worm''?', 'A **virus** is malicious code that attaches itself to a legitimate program/file and requires **human action (like opening a file)** to spread.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00445', 'insurance-exam-bank', 'Computer Awareness', 6, 16, 'What is ''phishing'' in the context of cybersecurity?', 'Phishing is a type of cyberattack where fraudsters send **deceptive emails, messages, or websites impersonating legitimate organisations** (like banks) to trick victims into revealing sensitive information such as passwords, OTPs, or card details.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00446', 'insurance-exam-bank', 'Computer Awareness', 6, 17, 'What is ''two-factor authentication'' (2FA)?', 'Two-factor authentication requires users to provide **two different types of verification** (e.g., a password plus an OTP sent to a registered mobile number) before gaining access to an account, significantly enhancing security over a single password alone.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00447', 'insurance-exam-bank', 'Computer Awareness', 6, 18, 'What is ''encryption'' in the context of data security?', 'Encryption is the process of **converting readable data (plaintext) into a coded, unreadable format (ciphertext)** using an algorithm and key, so that only authorised parties with the correct decryption key can access the original information.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00448', 'insurance-exam-bank', 'Computer Awareness', 6, 19, 'What is the full form of ''LAN'' and ''WAN''?', 'LAN stands for **Local Area Network** — a network confined to a small geographical area, like an office or building.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00449', 'insurance-exam-bank', 'Computer Awareness', 6, 20, 'What is the full form of ''URL''?', 'URL stands for **Uniform Resource Locator** — the complete web address used to locate a resource (webpage, file, image) on the internet.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00450', 'insurance-exam-bank', 'Computer Awareness', 6, 21, 'What is a ''web browser''? Name two examples.', 'A web browser is **software used to access and display web pages** on the internet.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00451', 'insurance-exam-bank', 'Computer Awareness', 6, 22, 'What is ''cloud computing''?', 'Cloud computing refers to the **delivery of computing services (storage, servers, databases, software) over the internet (''the cloud'')**, rather than relying on local hardware, allowing on-demand access and scalability without owning the underlying infrastructure.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00452', 'insurance-exam-bank', 'Computer Awareness', 6, 23, 'What are the three main service models of cloud computing?', 'The three main cloud service models are:
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00453', 'insurance-exam-bank', 'Computer Awareness', 6, 24, 'What is a ''database'', and what does DBMS stand for?', 'A database is an **organised collection of structured data** stored electronically.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00454', 'insurance-exam-bank', 'Computer Awareness', 6, 25, 'What does ''SQL'' stand for, and what is it used for?', 'SQL stands for **Structured Query Language**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00455', 'insurance-exam-bank', 'Computer Awareness', 6, 26, 'What is a ''spreadsheet'', and name one common spreadsheet application.', 'A spreadsheet is a software application used to **organise, analyse, and store data in tabular form** using rows and columns, supporting formulas and calculations.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00456', 'insurance-exam-bank', 'Computer Awareness', 6, 27, 'In MS Excel, what does the formula `=SUM(A1:A5)` do?', 'The formula `=SUM(A1:A5)` **adds up all the numeric values in cells A1 through A5** and displays the total in the cell where the formula is entered.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00457', 'insurance-exam-bank', 'Computer Awareness', 6, 28, 'In MS Word, what is the keyboard shortcut to make selected text bold?', 'The keyboard shortcut to make selected text bold in MS Word is **`Ctrl + B`**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00458', 'insurance-exam-bank', 'Computer Awareness', 6, 29, 'What is the keyboard shortcut to undo the last action in most applications?', 'The keyboard shortcut to undo the last action is **`Ctrl + Z`**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00459', 'insurance-exam-bank', 'Computer Awareness', 6, 30, 'What is the keyboard shortcut to copy and paste selected content?', 'The keyboard shortcut to **copy** is `Ctrl + C`, and the keyboard shortcut to **paste** is `Ctrl + V`.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00460', 'insurance-exam-bank', 'Computer Awareness', 6, 31, 'What does ''WWW'' stand for?', 'WWW stands for **World Wide Web** — an information system of interlinked hypertext documents accessed via the internet using web browsers.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00461', 'insurance-exam-bank', 'Computer Awareness', 6, 32, 'What is the difference between the ''Internet'' and the ''World Wide Web''?', 'The **Internet** is the vast, global **network of interconnected computer networks** that transmits data.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00462', 'insurance-exam-bank', 'Computer Awareness', 6, 33, 'What is the function of a ''modem''?', 'A modem (Modulator-Demodulator) **converts digital data from a computer into analog signals for transmission over telephone lines (and vice versa)**, enabling internet connectivity, especially in traditional broadband/DSL connections.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00463', 'insurance-exam-bank', 'Computer Awareness', 6, 34, 'What is the function of a ''router'' in networking?', 'A router is a networking device that **forwards data packets between different computer networks**, directing traffic efficiently between devices on a local network and the wider internet.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00464', 'insurance-exam-bank', 'Computer Awareness', 6, 35, 'What does ''Wi-Fi'' stand for, or rather what is it commonly used for?', 'Wi-Fi is a technology that uses **radio waves to provide wireless high-speed internet/network connectivity** between devices and a router, without the need for physical cables.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00465', 'insurance-exam-bank', 'Computer Awareness', 6, 36, 'What is the full form of ''USB''?', 'USB stands for **Universal Serial Bus** — a standard interface used to connect peripheral devices (like pen drives, keyboards, and printers) to a computer, and to transfer data and power.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00466', 'insurance-exam-bank', 'Computer Awareness', 6, 37, 'What is the function of an ''antivirus'' software?', 'Antivirus software is designed to **detect, prevent, and remove malicious software (malware)** such as viruses, worms, and trojans from a computer system, protecting data and system integrity.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00467', 'insurance-exam-bank', 'Computer Awareness', 6, 38, 'What is a ''Trojan Horse'' in the context of malware?', 'A Trojan Horse is malicious software that **disguises itself as a legitimate or useful program** to trick users into installing it, after which it can perform harmful actions like stealing data or creating backdoor access for attackers.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00468', 'insurance-exam-bank', 'Computer Awareness', 6, 39, 'What is the full form of ''ATM'' in banking, and what technology does it rely on?', 'ATM stands for **Automated Teller Machine**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00469', 'insurance-exam-bank', 'Computer Awareness', 6, 40, 'What is ''Core Banking Solution'' (CBS)?', 'CBS is a **centralised, networked banking system** that allows a bank''s branches to access applications from centralised data centres, enabling customers to conduct banking transactions (deposits, withdrawals, transfers) from **any branch, regardless of where their account is held**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00470', 'insurance-exam-bank', 'Computer Awareness', 6, 41, 'What does ''EFT'' stand for in the context of banking technology?', 'EFT stands for **Electronic Funds Transfer** — the electronic transfer of money from one bank account to another, without direct intervention by bank staff, encompassing systems like NEFT, RTGS, and IMPS.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00471', 'insurance-exam-bank', 'Computer Awareness', 6, 42, 'What is a ''digital signature'' used for?', 'A digital signature is a **cryptographic technique used to verify the authenticity and integrity of a digital document or message**, ensuring it has not been altered and confirming the identity of the sender, often legally recognised under IT laws.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00472', 'insurance-exam-bank', 'Computer Awareness', 6, 43, 'What is the function of ''OTP'' (One-Time Password) in online banking security?', 'An OTP is a **unique, single-use password valid only for one transaction or login session**, typically sent via SMS or an authenticator app, adding an extra layer of security beyond a static password for online banking transactions.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00473', 'insurance-exam-bank', 'Computer Awareness', 6, 44, 'What is ''malware''?', 'Malware (short for ''malicious software'') is any software **intentionally designed to cause damage, disrupt operations, or gain unauthorised access** to a computer system, including viruses, worms, trojans, spyware, and ransomware.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00474', 'insurance-exam-bank', 'Computer Awareness', 6, 45, 'What is ''ransomware''?', 'Ransomware is a type of malware that **encrypts a victim''s files or locks their system**, with the attacker demanding a ransom payment (often in cryptocurrency) in exchange for restoring access.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00475', 'insurance-exam-bank', 'Computer Awareness', 6, 46, 'What is the difference between ''bit'' and ''byte''?', 'A **bit** (binary digit) is the smallest unit of data in computing, representing either a **0 or 1**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00476', 'insurance-exam-bank', 'Computer Awareness', 6, 47, 'Convert the binary number 1010 into its decimal equivalent.', 'Binary `1010` represents `(1×2³) + (0×2²) + (1×2¹) + (0×2⁰) = 8 + 0 + 2 + 0 = 10`.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00477', 'insurance-exam-bank', 'Computer Awareness', 6, 48, 'Convert the decimal number 25 into its binary equivalent.', 'Dividing 25 repeatedly by 2: `25 = 16+8+1 = 2⁴+2³+2⁰`.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00478', 'insurance-exam-bank', 'Computer Awareness', 6, 49, 'What is the full form of ''ASCII''?', 'ASCII stands for **American Standard Code for Information Interchange** — a character encoding standard used to represent text (letters, digits, symbols) in computers using numeric codes (typically 7 or 8 bits per character).', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00479', 'insurance-exam-bank', 'Computer Awareness', 6, 50, 'What is the difference between ''LAN'' and ''MAN''?', '**LAN (Local Area Network)** covers a small area like a single building or campus.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00480', 'insurance-exam-bank', 'Computer Awareness', 6, 51, 'What does ''VPN'' stand for, and what is its purpose?', 'VPN stands for **Virtual Private Network**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00481', 'insurance-exam-bank', 'Computer Awareness', 6, 52, 'What is ''e-mail spoofing''?', 'Email spoofing is a technique where attackers **forge the sender''s email address** to make a fraudulent email appear to come from a trusted or legitimate source, often used in phishing attacks.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00482', 'insurance-exam-bank', 'Computer Awareness', 6, 53, 'What is the purpose of a ''CAPTCHA'' on websites?', 'CAPTCHA (Completely Automated Public Turing test to tell Computers and Humans Apart) is used to **verify that a website user is a human and not an automated bot**, typically by requiring the user to solve a simple visual or logical puzzle.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00483', 'insurance-exam-bank', 'Computer Awareness', 6, 54, 'What is ''phishing'' versus ''vishing''?', '**Phishing** is fraud conducted via **deceptive emails or fake websites**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00484', 'insurance-exam-bank', 'Computer Awareness', 6, 55, 'What is the full form of ''GUI''?', 'GUI stands for **Graphical User Interface** — a visual way of interacting with a computer using icons, windows, buttons, and menus, as opposed to a text-based command-line interface.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00485', 'insurance-exam-bank', 'Computer Awareness', 6, 56, 'What is a ''hyperlink''?', 'A hyperlink is a **clickable reference (text or image) within a document or webpage that takes the user to another location**, such as a different webpage, section, or file, when clicked.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00486', 'insurance-exam-bank', 'Computer Awareness', 6, 57, 'What is the function of a ''scanner'' as an input device?', 'A scanner is an input device that **converts physical documents, images, or photographs into digital form**, allowing them to be stored, edited, or transmitted electronically.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00487', 'insurance-exam-bank', 'Computer Awareness', 6, 58, 'What is the difference between a ''dot matrix printer'' and a ''laser printer''?', 'A **dot matrix printer** is an **impact printer** that forms characters using pins striking an ink ribbon, producing lower-quality but more durable (carbon-copy capable) output.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00488', 'insurance-exam-bank', 'Computer Awareness', 6, 59, 'What is a ''motherboard''?', 'A motherboard is the **main circuit board of a computer**, connecting the CPU, memory, storage, and other peripheral components, enabling them to communicate with each other.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00489', 'insurance-exam-bank', 'Computer Awareness', 6, 60, 'What is the function of the ''BIOS'' in a computer?', 'BIOS (Basic Input/Output System) is **firmware stored on a chip on the motherboard** that initialises hardware during the booting process and hands over control to the operating system.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00490', 'insurance-exam-bank', 'Computer Awareness', 6, 61, 'What is a ''kernel'' in an operating system?', 'The kernel is the **core component of an operating system** that manages system resources (CPU, memory, devices) and facilitates communication between hardware and software.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00491', 'insurance-exam-bank', 'Computer Awareness', 6, 62, 'What is ''multitasking'' in the context of an operating system?', 'Multitasking is the ability of an operating system to **execute multiple tasks or processes concurrently**, giving the appearance that several programs are running simultaneously by rapidly switching the CPU''s attention between them.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00492', 'insurance-exam-bank', 'Computer Awareness', 6, 63, 'What is the full form of ''PDF''?', 'PDF stands for **Portable Document Format** — a file format developed by Adobe that preserves the formatting and layout of a document regardless of the software, hardware, or operating system used to view it.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00493', 'insurance-exam-bank', 'Computer Awareness', 6, 64, 'What is ''data backup'', and why is it important?', 'Data backup is the process of **creating copies of data** to protect against accidental loss, corruption, hardware failure, or cyberattacks (like ransomware), ensuring that important information can be restored if the original is lost or damaged.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00494', 'insurance-exam-bank', 'Computer Awareness', 6, 65, 'What is the difference between ''SSD'' and ''HDD'' as storage devices?', '**HDD (Hard Disk Drive)** stores data on **spinning magnetic platters**, offering larger capacity at a lower cost but with slower access speeds.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00495', 'insurance-exam-bank', 'Computer Awareness', 6, 66, 'What is ''e-commerce''?', 'E-commerce refers to the **buying and selling of goods and services over the internet**, including online retail, electronic payments, and online banking transactions.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00496', 'insurance-exam-bank', 'Computer Awareness', 6, 67, 'What is the purpose of ''cookies'' in web browsing?', 'Cookies are **small text files stored on a user''s device by a website**, used to remember login sessions, preferences, and browsing activity, enabling personalised experiences on subsequent visits.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00497', 'insurance-exam-bank', 'Computer Awareness', 6, 68, 'What does ''URL'' typically consist of? Name its main parts.', 'A URL typically consists of the **protocol** (e.g., https://), the **domain name** (e.g., www.example.com), and the **path** to a specific resource/page on that domain (e.g., /page.html).', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00498', 'insurance-exam-bank', 'Computer Awareness', 6, 69, 'What is ''spyware''?', 'Spyware is malicious software that **secretly monitors a user''s activity and collects information** (such as browsing habits, keystrokes, or passwords) without the user''s knowledge or consent, often transmitting this data to a third party.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00499', 'insurance-exam-bank', 'Computer Awareness', 6, 70, 'What is the full form of ''OCR'' technology?', 'OCR stands for **Optical Character Recognition** — technology that converts scanned images of printed or handwritten text into machine-readable, editable digital text.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('insurance-q00500', 'insurance-exam-bank', 'Computer Awareness', 6, 71, 'What does ''RAM'' stand for, and is it volatile or non-volatile?', 'RAM stands for **Random Access Memory**.
